for path, methods in c['paths'].items():
    for method, op in methods.items():
        print(f"{method.upper()} {path} - {op.get('operationId', 'no-op')}")
        if 'requestBody' in op:
            rb = op['requestBody']['content']['application/json']['schema']
            if '$ref' in rb:
                print(f"  body: {rb['$ref']}")
            elif 'properties' in rb:
                print(f"  body: {list(rb.get('properties', {}).keys())}")
EOF

