python3 << 'EOF'
import json
c = json.load(open('/workspace/contracts/openapi.contract.json'))
# Get all unique error codes by endpoint
print('Error code enums per endpoint (for 400/401/403/404/409):')
for p, methods in c['paths'].items():
    for m, op in methods.items():
        if m not in ('get','post','put','patch','delete'): continue
        op_id = op.get('operationId', '')
        codes_per_status = {}
        for status, resp in op.get('responses', {}).items():
            if status == '200' or status == '201' or status == '101':
                continue
            schema = resp.get('content', {}).get('application/json', {}).get('schema', {})
            err_props = schema.get('properties', {})
            if 'code' in err_props and 'enum' in err_props['code']:
                codes_per_status[status] = err_props['code']['enum']
        if codes_per_status:
            print(f'\n{op_id}:')
            for s, codes in codes_per_status.items():
                print(f'  {s}: {codes}')
EOF

