package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"labdeliver/backend/internal/api"
	"labdeliver/backend/internal/audit"
	"labdeliver/backend/internal/boot"
	"labdeliver/backend/internal/config"
	"labdeliver/backend/internal/db"
	"labdeliver/backend/internal/realtime"
	"labdeliver/backend/internal/serviceability"
	"labdeliver/backend/internal/store"
)

func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)
	cfg := config.Load()

	if len(os.Args) > 1 && (os.Args[1] == "--migrate" || os.Args[1] == "-migrate") {
		runMigrate(cfg)
		return
	}

	pgPool, err := db.OpenPostgres(context.Background(), cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("postgres: %v", err)
	}
	defer pgPool.Close()

	if err := db.EnsureSchema(context.Background(), pgPool); err != nil {
		log.Fatalf("postgres schema: %v", err)
	}

	redisCli, err := db.OpenRedis(context.Background(), cfg.RedisURL)
	if err != nil {
		log.Fatalf("redis: %v", err)
	}
	defer redisCli.Close()

	realtimeHub := realtime.NewHub()
	auditLogger := audit.NewLogger(pgPool)
	realtimeSink := realtime.NewSink(realtimeHub)

	state := &api.State{
		Cfg:           cfg,
		PG:            pgPool,
		Redis:         redisCli,
		Hub:           realtimeHub,
		Audit:         auditLogger,
		Realtime:      realtimeSink,
		Serviceability: serviceability.NewEngine(pgPool, redisCli, auditLogger, realtimeSink),
	}
	api.InitState(state)

	if err := boot.EnsureAdmin(context.Background(), pgPool, cfg); err != nil {
		log.Fatalf("ensure admin: %v", err)
	}

	mux := api.NewRouter(state)

	// Static frontend (Vue build output).
	staticDir := staticFSPath()
	if staticDir != "" {
		mux.NoRoute(func(c *api.Context) {
			c.File(staticDir, c.Request.URL.Path)
		})
	}

	srv := &http.Server{
		Addr:              cfg.Addr(),
		Handler:           mux,
		ReadHeaderTimeout: 15 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		log.Printf("listening on %s", cfg.Addr())
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("listen: %v", err)
		}
	}()

	<-stop
	log.Printf("shutting down")
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		log.Printf("shutdown: %v", err)
	}
}

func staticFSPath() string {
	candidates := []string{
		filepath.Join("frontend", "dist"),
		filepath.Join("..", "frontend", "dist"),
	}
	for _, p := range candidates {
		if st, err := os.Stat(p); err == nil && st.IsDir() {
			return p
		}
	}
	return ""
}

func runMigrate(cfg config.Config) {
	pool, err := db.OpenPostgres(context.Background(), cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("postgres: %v", err)
	}
	defer pool.Close()
	if err := db.EnsureSchema(context.Background(), pool); err != nil {
		log.Fatalf("postgres schema: %v", err)
	}
	// Also reset serviceability snapshot cache + realtime counters in Redis.
	rds, err := db.OpenRedis(context.Background(), cfg.RedisURL)
	if err == nil {
		_ = store.CleanRedisForReset(context.Background(), rds)
		rds.Close()
	}
	fmt.Println("schema materialised")
}

