package config

import (
	"fmt"
	"os"
	"strconv"
)

type Config struct {
	Port          int
	DatabaseURL   string
	RedisURL      string
	MongoURI      string
	AdminUsername string
	AdminPassword string
	JWTSecret     string
	StaticDir     string
}

func Load() Config {
	cfg := Config{
		Port:          getEnvInt("PORT", 18082),
		DatabaseURL:   getEnv("DATABASE_URL", "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"),
		RedisURL:      getEnv("REDIS_URL", "redis://127.0.0.1:6379/0"),
		MongoURI:      getEnv("MONGODB_URI", "mongodb://127.0.0.1:27017/arena"),
		AdminUsername: getEnv("ADMIN_USERNAME", "admin"),
		AdminPassword: getEnv("ADMIN_PASSWORD", "admin1234"),
		JWTSecret:     getEnv("JWT_SECRET", "labdeliver-dev-secret-change-me"),
		StaticDir:     getEnv("STATIC_DIR", "frontend/dist"),
	}
	return cfg
}

func (c Config) Addr() string {
	return fmt.Sprintf("127.0.0.1:%d", c.Port)
}

func getEnv(k, fallback string) string {
	v := strings.TrimSpace(os.Getenv(k))
	if v == "" {
		return fallback
	}
	return v
}

func getEnvInt(k string, fallback int) int {
	v := strings.TrimSpace(os.Getenv(k))
	if v == "" {
		return fallback
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return fallback
	}
	return n
}

// avoid an extra import for strings
var _ = strings.TrimSpace

