	if err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password)); err != nil {
		return nil, ErrInvalidCredentials
	}
	activeRole := ""
	if len(roles) > 0 {
		activeRole = roles[0]
	}
	return &Session{UserID: userID, ActiveRole: activeRole, Roles: roles}, nil
}

// Issue creates a new session token (random string) and persists it.
func (s *Store) Issue(ctx context.Context, sess *Session, ttl time.Duration) (string, error) {
	token, err := newToken()
	if err != nil {
		return "", err
	}
	expires := time.Now().UTC().Add(ttl)
	_, err = s.pg.Exec(ctx, `
		INSERT INTO session_tokens (token, user_id, active_role, expires_at)
		VALUES ($1, $2, $3, $4)
	`, token, sess.UserID, sess.ActiveRole, expires)
	if err != nil {
		return "", err
	}
	return token, nil
}

// Lookup resolves a bearer [REDACTED] to a session.
func (s *Store) Lookup(ctx context.Context, token string) (*Session, error) {
	if token == "" {
		return nil, ErrUnauthorized
	}
	var (
		userID    uuid.UUID
		activeRole string
		expiresAt time.Time
		roles     []string
		active    bool
	)
	row := s.pg.QueryRow(ctx, `
		SELECT st.user_id, st.active_role, st.expires_at, u.roles, u.active
		FROM session_tokens st JOIN users u ON st.user_id = u.user_id
		WHERE st.token = $1
	`, token)
	if err := row.Scan(&userID, &activeRole, &expiresAt, &roles, &active); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, ErrUnauthorized
		}
		return nil, err
	}
	if !active || time.Now().UTC().After(expiresAt) {
		return nil, ErrUnauthorized
	}
	return &Session{UserID: userID, ActiveRole: activeRole, Roles: roles, ExpiresAt: expiresAt}, nil
}

func (s *Store) SetActiveRole(ctx context.Context, token, role string) error {
	_, err := s.pg.Exec(ctx, `UPDATE session_tokens SET active_role = $1 WHERE token = $2`, role, token)
	return err
}

func (s *Store) Revoke(ctx context.Context, token string) error {
	_, err := s.pg.Exec(ctx, `DELETE FROM session_tokens WHERE token = $1`, token)
	return err
}

func (s *Store) Cleanup(ctx context.Context) {
	_, _ = s.pg.Exec(ctx, `DELETE FROM session_tokens WHERE expires_at < NOW()`)
}

// HashPassword bcrypts the supplied password.
func HashPassword(pw string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(h), err
}

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrUnauthorized       = errors.New("unauthorized")
	ErrRoleNotHeld        = errors.New("role_not_held")
)

func newToken() (string, error) {
	u, err := uuid.NewRandom()
	if err != nil {
		return "", err
	}
	return strings.ReplaceAll(u.String(), "-", ""), nil
}

