package api

import (
	"errors"
	"log"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"

	"labdeliver/backend/internal/auth"
)

const sessionKey = "session"

func requestLogger() gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		c.Next()
		log.Printf("%-6s %-32s -> %d (%s) ua=%q", c.Request.Method, c.Request.URL.Path, c.Writer.Status(), time.Since(start), c.Request.UserAgent())
	}
}

// authRequired validates the bearer [REDACTED] and stores the session in the context.
func authRequired(s *State) gin.HandlerFunc {
	return func(c *gin.Context) {
		token := bearerToken(c.Request.Header.Get("Authorization"))
		if token == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
			return
		}
		sess, err := s.Auth.Lookup(c.Request.Context(), token)
		if err != nil {
			if errors.Is(err, auth.ErrUnauthorized) {
				c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
				return
			}
			c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{"error": "auth lookup failed", "code": "internal_error"})
			return
		}
		if sess.ActiveRole == "" {
			c.AbortWithStatusJSON(http.StatusConflict, gin.H{"error": "role not selected", "code": "role_not_selected"})
			return
		}
		c.Set(sessionKey, sess)
		c.Set("token", token)
		c.Next()
	}
}

// requireRole enforces a specific active role.
func requireRole(s *State, role string) gin.HandlerFunc {
	return func(c *gin.Context) {
		sess, _ := c.Get(sessionKey)
		if sess == nil {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
			return
		}
		cur := sess.(*auth.Session)
		if cur.ActiveRole != role {
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "forbidden", "code": "forbidden"})
			return
		}
		c.Next()
	}
}

// requireAnyRole enforces that the active role is one of the allowed list.
func requireAnyRole(s *State, roles ...string) gin.HandlerFunc {
	return func(c *gin.Context) {
		sess, _ := c.Get(sessionKey)
		if sess == nil {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
			return
		}
		cur := sess.(*auth.Session)
		ok := false
		for _, r := range roles {
			if cur.ActiveRole == r {
				ok = true
				break
			}
		}
		if !ok {
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "forbidden", "code": "forbidden"})
			return
		}
		c.Next()
	}
}

func bearerToken(h string) string {
	const prefix = "Bearer "
	if strings.HasPrefix(h, prefix) {
		return strings.TrimSpace(h[len(prefix):])
	}
	return ""
}

func currentSession(c *gin.Context) *auth.Session {
	v, ok := c.Get(sessionKey)
	if !ok {
		return nil
	}
	return v.(*auth.Session)
}

func currentToken(c *gin.Context) string {
	if t, ok := c.Get("token"); ok {
		if s, ok := t.(string); ok {
			return s
		}
	}
	return ""
}

