package serviceability

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/redis/go-redis/v9"

	"labdeliver/backend/internal/audit"
	"labdeliver/backend/internal/realtime"
)

type Engine struct {
	pg     *pgxpool.Pool
	rds    *redis.Client
	audit  *audit.Logger
	sink   *realtime.Sink
}

func NewEngine(pg *pgxpool.Pool, rds *redis.Client, audit *audit.Logger, sink *realtime.Sink) *Engine {
	return &Engine{pg: pg, rds: rds, audit: audit, sink: sink}
}

// ReasonCode enumerates serviceability failure reasons.
type ReasonCode string

const (
	ReasonServiceable           ReasonCode = "serviceable"
	ReasonOutsideCoverage       ReasonCode = "outside_service_coverage"
	ReasonNoAcceptingLab        ReasonCode = "no_accepting_laboratory"
	ReasonNoRoute               ReasonCode = "no_route"
	ReasonInsufficientCapacity  ReasonCode = "insufficient_capacity"
	ReasonDeadlineUnreachable   ReasonCode = "deadline_unreachable"
	ReasonHandlingUnsatisfiable ReasonCode = "handling_rules_unsatisfiable"
)

type CheckInput struct {
	Origin              Coordinate    `json:"origin"`
	OriginType          string        `json:"originType"`
	OriginNodeID        *uuid.UUID    `json:"originNodeId,omitempty"`
	SampleTypeID        uuid.UUID     `json:"sampleTypeId"`
	RequestedAt         time.Time     `json:"requestedAt"`
	DeliveryDeadline    time.Time     `json:"deliveryDeadline"`
	EarliestCollection  *time.Time    `json:"earliestCollectionAt,omitempty"`
	LatestCollection    *time.Time    `json:"latestCollectionAt,omitempty"`
	ContainerType       string        `json:"containerType,omitempty"`
	TemperatureMinC     float64       `json:"temperatureMinC,omitempty"`
	TemperatureMaxC     float64       `json:"temperatureMaxC,omitempty"`
	Incompatibilities   []uuid.UUID   `json:"incompatibleSampleTypes,omitempty"`
}

type CheckResult struct {
	Serviceable          bool       `json:"serviceable"`
	Reason               ReasonCode `json:"reason"`
	TargetLaboratoryID   *uuid.UUID `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt   *time.Time `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion int       `json:"serviceabilityVersion"`
	PathSummary          []uuid.UUID `json:"pathSummary,omitempty"`
}

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type ServiceabilitySnapshot struct {
	Version                   int         `json:"version"`
	Status                    string      `json:"status"`
	ComputedAt                time.Time   `json:"computedAt"`
	NetworkRevision           int         `json:"networkRevision"`
	Regions                   []Region    `json:"regions"`
	ActiveCollectionPointCount int        `json:"activeCollectionPointCount"`
}

type Region struct {
	LocationID uuid.UUID `json:"locationId"`
	Name       string    `json:"name"`
	Latitude   float64   `json:"latitude"`
	Longitude  float64   `json:"longitude"`
	CoverageKm float64   `json:"coverageKm"`
}

// BumpRevision increments network_revision and refreshes the serviceability snapshot.
func (e *Engine) BumpRevision(ctx context.Context, actorID *uuid.UUID, role string) error {
	_, err := e.pg.Exec(ctx, `UPDATE network_revision SET revision = revision + 1, updated_at = NOW()`)
	if err != nil {
		return err
	}
	_, err = e.Recompute(ctx)
	if err != nil {
		return err
	}
	e.audit.Write(ctx, audit.Entry{
		ActorID: actorID, Role: role, Action: "network_revision_bumped",
		EntityType: "network", EntityID: "global", Success: true,
	})
	e.sink.Emit(ctx, "network_revision_bumped", "network", "global", map[string]interface{}{})
	return nil
}

func (e *Engine) Recompute(ctx context.Context) (int, error) {
	var rev int
	if err := e.pg.QueryRow(ctx, `SELECT revision FROM network_revision LIMIT 1`).Scan(&rev); err != nil {
		return 0, err
	}
	regions, err := e.collectRegions(ctx)
	if err != nil {
		return 0, err
	}
	var nextVersion int
	if err := e.pg.QueryRow(ctx, `
		INSERT INTO serviceability_versions
		    (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES (
		    COALESCE((SELECT MAX(version) FROM serviceability_versions),0)+1,
		    'complete', NOW(), $1, $2::jsonb, $3
		)
		RETURNING version
	`, rev, toJSON(regions), len(regions)).Scan(&nextVersion); err != nil {
		return 0, err
	}
	cacheKey := fmt.Sprintf("svc:current:%d", nextVersion)
	payload, _ := json.Marshal(ServiceabilitySnapshot{
		Version: nextVersion, Status: "complete", ComputedAt: time.Now().UTC(),
		NetworkRevision: rev, Regions: regions, ActiveCollectionPointCount: len(regions),
	})
	_ = e.rds.Set(ctx, cacheKey, string(payload), 10*time.Minute).Err()
	return nextVersion, nil
}

func (e *Engine) LatestVersion(ctx context.Context) (ServiceabilitySnapshot, error) {
	var snap ServiceabilitySnapshot
	var regionsJSON []byte
	row := e.pg.QueryRow(ctx, `
		SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_versions
		ORDER BY version DESC LIMIT 1
	`)
	if err := row.Scan(&snap.Version, &snap.Status, &snap.ComputedAt, &snap.NetworkRevision, &regionsJSON, &snap.ActiveCollectionPointCount); err != nil {
		return snap, err
	}
	if len(regionsJSON) > 0 {
		_ = json.Unmarshal(regionsJSON, &snap.Regions)
	}
	return snap, nil
}

func (e *Engine) collectRegions(ctx context.Context) ([]Region, error) {
	rows, err := e.pg.Query(ctx, `
		SELECT location_id, name, latitude, longitude, coverage_km
		FROM locations
		WHERE active = TRUE AND functions ? 'collection_point'
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Region
	for rows.Next() {
		var r Region
		if err := rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// Check performs the synchronous serviceability dry-run.
func (e *Engine) Check(ctx context.Context, in CheckInput) (CheckResult, error) {
	res := CheckResult{Serviceability: false, Reason: ReasonHandlingUnsatisfiable, ServiceabilityVersion: 1}
	snap, err := e.LatestVersion(ctx)
	if err != nil {
		return res, err
	}
	res.ServiceabilityVersion = snap.Version

	// 1. Origin within 5km of an active collection point (or origin is a node/clinic inside).
	covered := false
	if in.OriginType == "node" && in.OriginNodeID != nil {
		covered = true
	} else {
		for _, r := range snap.Regions {
			if haversineKm(in.Origin.Latitude, in.Origin.Longitude, r.Latitude, r.Longitude) <= r.CoverageKm {
				covered = true
				break
			}
		}
	}
	if !covered {
		res.Reason = ReasonOutsideCoverage
		return res, nil
	}

	// 2. Sample type metadata.
	var (
		stRequiresCooled bool
		stContainer      string
		stTempMin        float64
		stTempMax        float64
		stBatchAllowed   bool
	)
	row := e.pg.QueryRow(ctx, `
		SELECT requires_cooled_route, container_type, temperature_min_c, temperature_max_c, batching_allowed
		FROM sample_types WHERE sample_type_id = $1
	`, in.SampleTypeID)
	if err := row.Scan(&stRequiresCooled, &stContainer, &stTempMin, &stTempMax, &stBatchAllowed); err != nil {
		res.Reason = ReasonHandlingUnsatisfiable
		return res, nil
	}
	if stRequiresCooled {
		// Will require cooled route / lab capacity (checked during route search).
	}

	// 3. Find accepting laboratory.
	labRows, err := e.pg.Query(ctx, `
		SELECT la.laboratory_id, l.name, l.latitude, l.longitude
		FROM laboratory_acceptance la
		JOIN locations l ON l.location_id = la.laboratory_id
		WHERE la.sample_type_id = $1 AND la.accepts = TRUE AND l.active = TRUE
	`, in.SampleTypeID)
	if err != nil {
		return res, err
	}
	defer labRows.Close()
	type labOpt struct {
		id       uuid.UUID
		name     string
		lat, lon float64
	}
	var labs []labOpt
	for labRows.Next() {
		var lo labOpt
		if err := labRows.Scan(&lo.id, &lo.name, &lo.lat, &lo.lon); err != nil {
			return res, err
		}
		labs = append(labs, lo)
	}
	if len(labs) == 0 {
		res.Reason = ReasonNoAcceptingLab
		return res, nil
	}

	// 4. Find a valid route from each candidate collection point to each lab.
	collectionPoints := snap.Regions
	if in.OriginType == "node" && in.OriginNodeID != nil {
		// origin is a node - start at origin node.
		collectionPoints = nil
		var originNode Region
		if err := e.pg.QueryRow(ctx, `SELECT location_id, name, latitude, longitude, coverage_km FROM locations WHERE location_id = $1 AND active = TRUE`, in.OriginNodeID).
			Scan(&originNode.LocationID, &originNode.Name, &originNode.Latitude, &originNode.Longitude, &originNode.CoverageKm); err == nil {
			collectionPoints = []Region{originNode}
		}
	}

	bestETA := time.Time{}
	var bestPath []uuid.UUID
	var bestLab uuid.UUID
	routeFound := false
	for _, cp := range collectionPoints {
		for _, lab := range labs {
			path, travelMin, ok := shortestPath(ctx, e.pg, cp.LocationID, lab.id, stRequiresCooled)
			if !ok {
				continue
			}
			eta := in.RequestedAt.Add(time.Duration(travelMin) * time.Minute)
			if !eta.Before(in.DeliveryDeadline) {
				continue
			}
			if !routeFound || eta.Before(bestETA) {
				routeFound = true
				bestETA = eta
				bestPath = path
				bestLab = lab.id
			}
		}
	}
	if !routeFound {
		res.Reason = ReasonNoRoute
		return res, nil
	}

	// 5. Capacity check.
	if !capacityCheck(ctx, e.pg, bestPath, stRequiresCooled) {
		res.Reason = ReasonInsufficientCapacity
		return res, nil
	}

	res.Serviceable = true
	res.Reason = ReasonServiceable
	res.TargetLaboratoryID = &bestLab
	res.EstimatedArrivalAt = &bestETA
	res.PathSummary = bestPath
	return res, nil
}

func capacityCheck(ctx context.Context, pg *pgxpool.Pool, path []uuid.UUID, cooled bool) bool {
	if len(path) < 2 {
		return true
	}
	// Check node storage and connection capacity for path.
	for i := 0; i < len(path); i++ {
		id := path[i]
		if i > 0 {
			// Connection from path[i-1] -> path[i]
			var (
				capacity, reserved, cooledCap, cooledRes int
				isCooled bool
			)
			if err := pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, cooled FROM connections WHERE from_location_id = $1 AND to_location_id = $2 AND active = TRUE`, path[i-1], id).
				Scan(&capacity, &reserved, &cooledCap, &cooledRes, &isCooled); err != nil {
				return false
			}
			if cooled {
				if !isCooled {
					return false
				}
				if cooledCap-cooledRes < 1 {
					return false
				}
			} else if capacity-reserved < 1 {
				return false
			}
		}
		if i < len(path)-1 {
			var capU, resU, cCap, cRes int
			if err := pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE location_id = $1`, id).
				Scan(&capU, &resU, &cCap, &cRes); err != nil {
				return false
			}
			if cooled {
				if cCap-cRes < 1 {
					return false
				}
			} else if capU-resU < 1 {
				return false
			}
		}
	}
	return true
}

// shortestPath finds the shortest path (by travel minutes) between two locations
// that satisfies cooled constraints. Returns the path and total travel minutes.
func shortestPath(ctx context.Context, pg *pgxpool.Pool, from, to uuid.UUID, cooled bool) ([]uuid.UUID, int, bool) {
	// Dijkstra with priority queue stored in map for simplicity.
	type state struct {
		id    uuid.UUID
		cost  int
		prior uuid.UUID
	}
	dist := map[uuid.UUID]int{from: 0}
	prev := map[uuid.UUID]uuid.UUID{}
	pq := map[uuid.UUID]int{from: 0}
	for len(pq) > 0 {
		var cur uuid.UUID
		curCost := math.MaxInt32
		for id, c := range pq {
			if c < curCost {
				curCost = c
				cur = id
			}
		}
		delete(pq, cur)
		if cur == to {
			break
		}
		rows, err := pg.Query(ctx, `
			SELECT to_location_id, travel_minutes, cooled
			FROM connections
			WHERE from_location_id = $1 AND active = TRUE
		`, cur)
		if err != nil {
			return nil, 0, false
		}
		for rows.Next() {
			var next uuid.UUID
			var travel int
			var isCooled bool
			if err := rows.Scan(&next, &travel, &isCooled); err != nil {
				rows.Close()
				return nil, 0, false
			}
			if cooled && !isCooled {
				continue
			}
			nd := curCost + travel
			if existing, ok := dist[next]; !ok || nd < existing {
				dist[next] = nd
				prev[next] = cur
				pq[next] = nd
			}
		}
		rows.Close()
	}
	finalCost, ok := dist[to]
	if !ok {
		return nil, 0, false
	}
	// reconstruct path
	var path []uuid.UUID
	for cur := to; cur != uuid.Nil; cur = prev[cur] {
		path = append([]uuid.UUID{cur}, path...)
		if cur == from {
			break
		}
	}
	if len(path) == 0 || path[0] != from {
		return nil, 0, false
	}
	return path, finalCost, true
}

func toJSON(v interface{}) string {
	b, _ := json.Marshal(v)
	return string(b)
}

// haversineKm returns the great-circle distance between two coordinates in kilometres.
func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	rad := math.Pi / 180
	dLat := (lat2 - lat1) * rad
	dLon := (lon2 - lon1) * rad
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*rad)*math.Cos(lat2*rad)*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

