			if err := pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, cooled FROM connections WHERE from_location_id = $1 AND to_location_id = $2 AND active = TRUE`, path[i-1], id).
				Scan(&capacity, &reserved, &cooledCap, &cooledRes, &isCooled); err != nil {
