package boot

import (
	"context"
	"errors"
	"fmt"
	"log"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"labdeliver/backend/internal/auth"
	"labdeliver/backend/internal/config"
)

// EnsureAdmin creates the first administrator account when no users exist.
// Calling this when users already exist is a no-op.
func EnsureAdmin(ctx context.Context, pg *pgxpool.Pool, cfg config.Config) error {
	var count int
	if err := pg.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
		return fmt.Errorf("count users: %w", err)
	}
	if count > 0 {
		return nil
	}
	hash, err := auth.HashPassword(cfg.AdminPassword)
	if err != nil {
		return fmt.Errorf("hash admin password: %w", err)
	}
	uid := uuid.New()
	_, err = pg.Exec(ctx, `
		INSERT INTO users (user_id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, available, capacity_units)
		VALUES ($1, $2, $3, $4, $5, '', ARRAY['administrator']::TEXT[], '{}'::TEXT[], '[]'::jsonb, TRUE, TRUE, 100)
	`, uid, cfg.AdminUsername, hash, "", cfg.AdminUsername)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil
		}
		return fmt.Errorf("insert admin: %w", err)
	}
	log.Printf("created initial administrator username=%s", cfg.AdminUsername)
	return nil
}

