// APIError describes a typed error envelope.
type APIError struct {
	HTTPStatus int    `json:"-"`
	Code       string `json:"code"`
	Message    string `json:"error"`
}

func (e APIError) Error() string { return fmt.Sprintf("%s: %s", e.Code, e.Message) }

// Err returns an APIError with the provided code and message.
func Err(httpStatus int, code, message string) APIError {
	return APIError{HTTPStatus: httpStatus, Code: code, Message: message}
}

// WriteError writes the error envelope in the contract's shape.
func WriteError(c *gin.Context, err APIError) {
	c.JSON(err.HTTPStatus, gin.H{"error": err.Message, "code": err.Code})
}

// ReadBody reads the JSON body into the supplied target, returning APIError on failure.
func ReadBody(c *gin.Context, target interface{}) error {
	if c.Request.Body == nil {
		return Err(http.StatusBadRequest, "invalid_json", "missing body")
	}
	defer c.Request.Body.Close()
	dec := json.NewDecoder(c.Request.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(target); err != nil {
		if errors.Is(err, io.EOF) {
			return Err(http.StatusBadRequest, "invalid_json", "empty body")
		}
		return Err(http.StatusBadRequest, "invalid_json", err.Error())
	}
	return nil
}

// UUID returns a parsed UUID or an error.
func UUID(c *gin.Context, field, value string) (uuid.UUID, error) {
	id, err := uuid.Parse(value)
	if err != nil {
		return uuid.Nil, Err(http.StatusBadRequest, "invalid_json", fmt.Sprintf("invalid %s uuid", field))
	}
	return id, nil
}

// UUIDPtr returns a parsed UUID pointer or an error.
func UUIDPtr(c *gin.Context, field string, value *string) (*uuid.UUID, error) {
	if value == nil || *value == "" {
		return nil, nil
	}
	id, err := uuid.Parse(*value)
	if err != nil {
		return nil, Err(http.StatusBadRequest, "invalid_json", fmt.Sprintf("invalid %s uuid", field))
	}
	return &id, nil
}

// wrapPGNoRows converts pgx.ErrNoRows into a 404 APIError.
func wrapPGNoRows(err error) error {
	if errors.Is(err, pgx.ErrNoRows) {
		return Err(http.StatusNotFound, "not_found", "not found")
	}
	return err
}

// loadUser pulls a user row, returning 404 on missing rows.
func loadUser(ctx interface{ /* placeholder */ }, db store.UserLookup) (store.User, error) {
	_ = ctx
	return db, nil
}

// parseUUIDSlice converts a []string of UUIDs to []uuid.UUID.
func parseUUIDSlice(values []string) ([]uuid.UUID, error) {
	out := make([]uuid.UUID, 0, len(values))
	for _, v := range values {
		id, err := uuid.Parse(v)
		if err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, nil
}

