package api

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"

	"labdeliver/backend/internal/auth"
)

// handleAuthenticate processes /api/authenticate-user.
func handleAuthenticate(c *gin.Context) {
	var in struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Username == "" || in.Password == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "username and password required"))
		return
	}
	ctx := c.Request.Context()
	sess, err := globalState.Auth.Authenticate(ctx, in.Username, in.Password)
	if err != nil {
		if errors.Is(err, auth.ErrInvalidCredentials) {
			WriteError(c, Err(http.StatusUnauthorized, "invalid_credentials", "invalid credentials"))
			return
		}
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "authentication failed"))
		return
	}
	token, err := globalState.Auth.Issue(ctx, sess, 8*time.Hour)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "session issue failed"))
		return
	}
	auditWrite(ctx, nil, "auth", "authenticate", "user", sess.UserID.String(), true, map[string]any{
		"username": in.Username,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"sessionToken": token,
		"userId":       sess.UserID,
		"roles":        sess.Roles,
		"activeRole":   sess.ActiveRole,
	}})
}

// handleSelectActiveRole switches the active role for the current session.
func handleSelectActiveRole(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		Role string `json:"role"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Role == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_role", "role required"))
		return
	}
	has := false
	for _, r := range sess.Roles {
		if r == in.Role {
			has = true
			break
		}
	}
	if !has {
		WriteError(c, Err(http.StatusForbidden, "role_not_held", "role not held by user"))
		return
	}
	if err := globalState.Auth.SetActiveRole(c.Request.Context(), currentToken(c), in.Role); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "could not switch role"))
		return
	}
	sess.ActiveRole = in.Role
	auditWrite(c.Request.Context(), &sess.UserID, in.Role, "select_active_role", "user", sess.UserID.String(), true, nil)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"activeRole": in.Role,
		"roles":      sess.Roles,
	}})
}

// handleSignOut revokes the bearer [REDACTED]
func handleSignOut(c *gin.Context) {
	sess := currentSession(c)
	token := currentToken(c)
	if err := globalState.Auth.Revoke(c.Request.Context(), token); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "sign-out failed"))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "sign_out", "user", sess.UserID.String(), true, nil)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"success": true}})
}

// handleUIBootstrap returns the data the front-end needs to render.
func handleUIBootstrap(c *gin.Context) {
	sess := currentSession(c)
	ctx := c.Request.Context()
	user, err := loadUserRow(ctx, sess.UserID)
	if err != nil {
		WriteError(c, err.(APIError))
		return
	}
	boot := gin.H{
		"user": gin.H{
			"userId":               user.UserID,
			"username":             user.Username,
			"fullName":             user.FullName,
			"roles":                user.Roles,
			"activeRole":           sess.ActiveRole,
			"roleSelectionRequired": sess.ActiveRole == "" && len(user.Roles) > 0,
		},
		"serverTime": time.Now().UTC().Format(time.RFC3339Nano),
	}
	if hasAnyRole(sess, "administrator", "dispatcher") {
		ops, _ := buildOperationsState(ctx, &opsFilters{})
		boot["operations"] = ops
	}
	if hasAnyRole(sess, "requester") {
		samples, _ := loadRequesterSamples(ctx, sess.UserID)
		boot["requesterSamples"] = samples
	}
	c.JSON(http.StatusOK, gin.H{"data": boot})
}

// handleReadUser returns a user record by id.
func handleReadUser(c *gin.Context) {
	id, err := uuid.Parse(c.Param("userId"))
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid userId"))
		return
	}
	user, err := loadUserRow(c.Request.Context(), id)
	if err != nil {
		WriteError(c, err.(APIError))
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"userId":         user.UserID,
		"username":       user.Username,
		"email":          user.Email,
		"fullName":       user.FullName,
		"phone":          user.Phone,
		"roles":          user.Roles,
		"qualifications": user.Qualifications,
		"certifications": user.Certifications,
		"active":         user.Active,
	}})
}

// auditWrite is a thin wrapper around the audit logger.
func auditWrite(ctx context.Context, actor *uuid.UUID, role, action, entityType, entityID string, success bool, details map[string]any) {
	if globalState == nil || globalState.Audit == nil {
		return
	}
	if details == nil {
		details = map[string]any{}
	}
	globalState.Audit.Write(ctx, auditEntry(actor, role, action, entityType, entityID, success, details))
}

