		return
	}
	if len(in.Roles) == 0 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "at least one role required"))
		return
	}
	if err := validateRoles(in.Roles); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.UserID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid userId"))
		return
	}
