	}
	hash, err := auth.HashPassword(in.InitialPassword)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "hash failure"))
		return
	}
	id := uuid.New()
	certs, _ := json.Marshal(in.Certifications)
	assigned := uuid.Nil
	if in.AssignedLocationID != nil && *in.AssignedLocationID != "" {
		assigned, err = uuid.Parse(*in.AssignedLocationID)
		if err != nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignedLocationId"))
			return
		}
	}
	if assigned != uuid.Nil {
		// validate exists
		var exists bool
		_ = globalState.PG.QueryRow(c.Request.Context(), `SELECT EXISTS(SELECT 1 FROM locations WHERE location_id=$1)`, assigned).Scan(&exists)
		if !exists {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "assignedLocationId not found"))
			return
		}
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO users (user_id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, assigned_location_id, active, available, capacity_units)
		VALUES ($1,$2,$3,NULLIF($4,''),NULLIF($5,''),NULLIF($6,''),$7,$8,$9::jsonb,$10,$11,TRUE,$12)
	`, id, in.Username, hash, in.Email, in.FullName, in.Phone, in.Roles, in.Qualifications, string(certs), nullUUID(assigned), in.Active, 5)
	if err != nil {
		WriteError(c, Err(http.StatusConflict, "duplicate_user", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "create_user", "user", id.String(), true, map[string]any{
		"username": in.Username, "roles": in.Roles,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"userId": id}})
}

// handleUpdateUserAccess updates role/qualification/certification/active status.
func handleUpdateUserAccess(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		UserID             string        `json:"userId"`
		Roles              []string      `json:"roles"`
		Qualifications     []string      `json:"qualifications"`
		Certifications     []store.Cert  `json:"certifications"`
		Active             bool          `json:"active"`
		AssignedLocationID *string       `json:"assignedLocationId"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.UserID == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "userId required"))
		return
	}
	if len(in.Roles) == 0 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "at least one role required"))
		return
	}
	if err := validateRoles(in.Roles); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.UserID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid userId"))
		return
	}
	var assigned *uuid.UUID
	if in.AssignedLocationID != nil && *in.AssignedLocationID != "" {
		a, err := uuid.Parse(*in.AssignedLocationID)
		if err != nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignedLocationId"))
			return
		}
		assigned = &a
	}
	certs, _ := json.Marshal(in.Certifications)
	_, err = globalState.PG.Exec(c.Request.Context(), `
		UPDATE users SET roles=$1, qualifications=$2, certifications=$3::jsonb, active=$4, assigned_location_id=$5, updated_at=NOW()
		WHERE user_id=$6
	`, in.Roles, in.Qualifications, string(certs), in.Active, assigned, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "update_user_access", "user", id.String(), true, map[string]any{
		"roles": in.Roles, "active": in.Active,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"userId": id}})
}

// handleSetWorkerAvailability updates a worker's availability and capacity units.
func handleSetWorkerAvailability(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.WorkerID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid workerId"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `
		UPDATE users SET available=$1, capacity_units=$2, updated_at=NOW() WHERE user_id=$3
	`, in.Available, in.CapacityUnits, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "set_worker_availability", "user", id.String(), true, map[string]any{
		"available": in.Available, "capacityUnits": in.CapacityUnits,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"workerId":      id,
		"available":     in.Available,
		"capacityUnits": in.CapacityUnits,
	}})
}

// validateRoles checks the supplied roles against the allowed enum.
func validateRoles(roles []string) APIError {
	allowed := map[string]bool{
		"administrator": true, "dispatcher": true, "requester": true,
		"collection_professional": true, "delivery_partner": true,
		"node_handler": true, "laboratory_team": true,
	}
	for _, r := range roles {
		if !allowed[r] {
			return Err(http.StatusBadRequest, "invalid_role", "unknown role "+r)
		}
	}
	return APIError{}
}

func hasAnyRole(sess interface{}, roles ...string) bool {
	cs, ok := sess.(*auth.Session)
	if !ok {
		return false
	}
	for _, r := range roles {
		if cs.ActiveRole == r {
			return true
		}
	}
	return false
}

func nullUUID(id uuid.UUID) interface{} {
	if id == uuid.Nil {
		return nil
	}
	return id
}

// helper used elsewhere
var _ = time.RFC3339

