package api

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"labdeliver/backend/internal/store"
)

// locationFunctions holds the current booleans for each function name.
func locationFunctions(states map[string]bool) map[string]any {
	if states == nil {
		states = map[string]bool{}
	}
	all := []string{"collection_point", "transfer_point", "hub", "laboratory"}
	out := map[string]any{}
	for _, fn := range all {
		out[fn] = states[fn]
	}
	return out
}

func functionsToMap(in []string) map[string]bool {
	out := map[string]bool{}
	for _, f := range in {
		out[f] = true
	}
	return out
}

func loadLocationRow(ctx interface{ /* unused */ }, id uuid.UUID) (store.Location, APIError) {
	row := globalState.PG.QueryRow(ctxAsCtx(ctx), `
		SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions,
		       capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations WHERE location_id = $1
	`, id)
	var loc store.Location
	var fnJSON []byte
	if err := row.Scan(&loc.LocationID, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude,
		&loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &fnJSON,
		&loc.CapacityUnits, &loc.ReservedUnits, &loc.CooledCapacityUnits, &loc.CooledReservedUnits); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return loc, Err(http.StatusNotFound, "not_found", "location not found")
		}
		return loc, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	if fnJSON != nil {
		_ = json.Unmarshal(fnJSON, &loc.Functions)
	}
	return loc, APIError{}
}

func ctxAsCtx(ctx interface{}) interfaceCtx {
	if v, ok := ctx.(interfaceCtx); ok {
		return v
	}
	return ctx.(contextWrapper)
}

// handleCreateLocation creates a network location.
func handleCreateLocation(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		Name            string   `json:"name"`
		Coordinate      coord    `json:"coordinate"`
		CoverageKm      float64  `json:"coverageKm"`
		HandlingMinutes int      `json:"handlingMinutes"`
		Active          bool     `json:"active"`
		Functions       []string `json:"functions"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Name == "" || len(in.Functions) == 0 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "name and functions required"))
		return
	}
	if in.CoverageKm <= 0 {
		in.CoverageKm = 5
	}
	if in.CoverageKm > 5 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "coverageKm must be <= 5"))
		return
	}
	if in.HandlingMinutes < 0 || in.HandlingMinutes > 1440 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "handlingMinutes out of range"))
		return
	}
	fn := functionsToMap(in.Functions)
	fnJSON, _ := json.Marshal(fn)
	id := uuid.New()
	_, err := globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO locations (location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,0,0,0,0)
	`, id, in.Name, in.Coordinate.Latitude, in.Coordinate.Longitude, in.CoverageKm, in.HandlingMinutes, in.Active, string(fnJSON))
	if err != nil {
		WriteError(c, Err(http.StatusConflict, "duplicate_location", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "create_location", "location", id.String(), true, map[string]any{
		"name": in.Name, "functions": in.Functions,
	})
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "serviceability recompute failed: "+err.Error()))
		return
	}
	globalState.Realtime.Emit(c.Request.Context(), "location_created", "location", id.String(), map[string]any{
		"name": in.Name,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"locationId": id}})
}

// handleUpdateLocation updates an existing location.
func handleUpdateLocation(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		LocationID      string   `json:"locationId"`
		Name            string   `json:"name"`
		Coordinate      coord    `json:"coordinate"`
		CoverageKm      *float64 `json:"coverageKm"`
		HandlingMinutes *int     `json:"handlingMinutes"`
		Functions       []string `json:"functions"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.LocationID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid locationId"))
		return
	}
	if in.CoverageKm != nil && (*in.CoverageKm <= 0 || *in.CoverageKm > 5) {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "coverageKm out of range"))
		return
	}
	fn := functionsToMap(in.Functions)
	fnJSON, _ := json.Marshal(fn)
	_, err = globalState.PG.Exec(c.Request.Context(), `
		UPDATE locations SET name=$2, latitude=$3, longitude=$4, coverage_km=COALESCE($5,coverage_km), handling_minutes=COALESCE($6,handling_minutes), functions=$7::jsonb, updated_at=NOW()
		WHERE location_id = $1
	`, id, in.Name, in.Coordinate.Latitude, in.Coordinate.Longitude, in.CoverageKm, in.HandlingMinutes, string(fnJSON))
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "update_location", "location", id.String(), true, nil)
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "serviceability recompute failed: "+err.Error()))
		return
	}
	globalState.Realtime.Emit(c.Request.Context(), "location_updated", "location", id.String(), nil)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"locationId": id}})
}

// handleSetLocationStatus activates/deactivates a whole location.
func handleSetLocationStatus(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		LocationID string `json:"locationId"`
		Active     bool   `json:"active"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.LocationID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid locationId"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE locations SET active=$2, updated_at=NOW() WHERE location_id=$1`, id, in.Active)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "set_location_status", "location", id.String(), true, map[string]any{"active": in.Active})
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "serviceability recompute failed: "+err.Error()))
		return
	}
	globalState.Realtime.Emit(c.Request.Context(), "location_status_changed", "location", id.String(), map[string]any{"active": in.Active})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"locationId": id, "active": in.Active}})
}

// handleSetLocationFunctionStatus toggles a single function.
func handleSetLocationFunctionStatus(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		LocationID string `json:"locationId"`
		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.LocationID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid locationId"))
		return
	}
	allowed := map[string]bool{"collection_point": true, "transfer_point": true, "hub": true, "laboratory": true}
	if !allowed[in.Function] {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "unknown function"))
		return
	}
	// Fetch existing functions
	loc, apierr := loadLocationRow(c, id)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	loc.Functions[in.Function] = in.Active
	fnJSON, _ := json.Marshal(loc.Functions)
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE locations SET functions=$2::jsonb, updated_at=NOW() WHERE location_id=$1`, id, string(fnJSON))
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "set_location_function_status", "location", id.String(), true, map[string]any{
		"function": in.Function, "active": in.Active,
	})
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "serviceability recompute failed: "+err.Error()))
		return
	}
	globalState.Realtime.Emit(c.Request.Context(), "location_function_changed", "location", id.String(), map[string]any{
		"function": in.Function, "active": in.Active,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"locationId": id,
		"function":   in.Function,
		"active":     in.Active,
		"functions":  locationFunctions(loc.Functions),
	}})
}

// handleCreateConnection creates a directed connection.
func handleCreateConnection(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.TravelMinutes < 1 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "travelMinutes must be >= 1"))
		return
	}
	from, err := uuid.Parse(in.FromLocationID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid fromLocationId"))
		return
	}
	to, err := uuid.Parse(in.ToLocationID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid toLocationId"))
		return
	}
	id := uuid.New()
	_, err = globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
		VALUES ($1,$2,$3,$4,$5,$6,$7,1,0,1,0)
	`, id, from, to, in.TravelMinutes, in.CostUnits, in.Cooled, in.Active)
	if err != nil {
		WriteError(c, Err(http.StatusConflict, "duplicate_connection", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "create_connection", "connection", id.String(), true, map[string]any{
		"from": from.String(), "to": to.String(), "cooled": in.Cooled,
	})
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "serviceability recompute failed"))
		return
	}
	globalState.Realtime.Emit(c.Request.Context(), "connection_created", "connection", id.String(), nil)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"connectionId": id}})
}

// handleSetConnectionStatus activates or deactivates a connection.
func handleSetConnectionStatus(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		ConnectionID string `json:"connectionId"`
		Active       bool   `json:"active"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.ConnectionID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid connectionId"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE connections SET active=$2 WHERE connection_id=$1`, id, in.Active)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "set_connection_status", "connection", id.String(), true, map[string]any{
		"active": in.Active,
	})
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "serviceability recompute failed"))
		return
	}
	globalState.Realtime.Emit(c.Request.Context(), "connection_status_changed", "connection", id.String(), map[string]any{"active": in.Active})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"connectionId": id, "active": in.Active}})
}

// coord matches the OpenAPI Coordinate schema.
type coord struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

// interfaceCtx and contextWrapper exist so the helper above compiles
// uniformly for tests and runtime.
type (
	interfaceCtx = interface{}
	contextWrapper = interface{}
)

