		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "name and containerType required"))
		return
	}
	if in.BatchingAllowed == nil {
		t := true
		in.BatchingAllowed = &t
	}
	id := uuid.New()
	_, err := globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO sample_types (sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
		VALUES ($1,$2,$3,NULLIF($4,''),$5,$6,$7,$8,$9,$10)
	`, id, in.Name, in.QualifiedCollectorReq, in.RequiredQualification, in.ContainerType, in.TemperatureMinC, in.TemperatureMaxC, in.IncompatibleSampleTypes, in.RequiresCooledRoute, *in.BatchingAllowed)
