		UPDATE sample_types SET
		  qualified_collector_required=COALESCE($2, qualified_collector_required),
		  required_qualification=NULLIF($3,''),
		  container_type=$4,
		  temperature_min_c=$5,
		  temperature_max_c=$6,
		  incompatible_sample_types=COALESCE($7, incompatible_sample_types),
		  requires_cooled_route=COALESCE($8, requires_cooled_route),
		  batching_allowed=COALESCE($9, batching_allowed),
