	ActiveRole string
}

func currentSession(c *gin.Context) *authSessionShim {
	v, ok := c.Get("session")
	if !ok {
		return &authSessionShim{}
	}
	s, _ := v.(*authSessionShim)
	return s
}

func currentToken(c *gin.Context) string {
	if v, ok := c.Get("token"); ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

func ptrString(p *uuid.UUID) string {
	if p == nil {
		return ""
	}
	return p.String()
}

func isStale(t *time.Time) bool {
	if t == nil {
		return true
	}
	return time.Since(*t) > 30*time.Minute
}

func idempotencyLookup(ctx context.Context, key string) (gin.H, bool) {
	val, err := globalState.Redis.Get(ctx, "idem:"+key).Result()
	if err != nil || val == "" {
		return nil, false
	}
	var out gin.H
	if err := json.Unmarshal([]byte(val), &out); err != nil {
		return nil, false
	}
	return out, true
}

func idempotencyStore(ctx context.Context, key string, v gin.H) {
	if globalState == nil || globalState.Redis == nil {
		return
	}
	b, _ := json.Marshal(v)
	_ = globalState.Redis.Set(ctx, "idem:"+key, string(b), 24*time.Hour).Err()
}

var _ = json.Marshal

