	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleTypeId"))
		return
	}
	requester, err := uuid.Parse(orDefault(in.RequesterID, sess.UserID.String()))
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid requesterId"))
		return
	}
	requestedAt, err := time.Parse(time.RFC3339Nano, in.RequestedAt)
	if err != nil {
		requestedAt, _ = time.Parse(time.RFC3339, in.RequestedAt)
	}
	deadline, err := time.Parse(time.RFC3339Nano, in.DeliveryDeadline)
	if err != nil {
		deadline, _ = time.Parse(time.RFC3339, in.DeliveryDeadline)
	}
	var earliest, latest time.Time
	if in.EarliestCollectionAt != nil {
		earliest, _ = time.Parse(time.RFC3339Nano, *in.EarliestCollectionAt)
	}
	if in.LatestCollectionAt != nil {
		latest, _ = time.Parse(time.RFC3339Nano, *in.LatestCollectionAt)
	}
	if earliest.IsZero() {
		earliest = requestedAt
	}
	if latest.IsZero() {
		latest = deadline.Add(-30 * time.Minute)
	}
	// Load sample type attributes.
	stRow := globalState.PG.QueryRow(c.Request.Context(), `
		SELECT qualified_collector_required, COALESCE(required_qualification,''), container_type, temperature_min_c, temperature_max_c, COALESCE(incompatible_sample_types, '{}'), requires_cooled_route, batching_allowed
