	if err := stRow.Scan(&qualReq, &qual, &ct, &minC, &maxC, &incomp, &cooled, &batchOK); err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "sample type not found"))
		return
	}
	if in.ContainerType != "" {
		ct = in.ContainerType
	}
	if in.TemperatureMinC != 0 || in.TemperatureMaxC != 0 {
		minC = in.TemperatureMinC
		maxC = in.TemperatureMaxC
	}
	var originNode *uuid.UUID
	if in.OriginNodeID != nil && *in.OriginNodeID != "" {
		on, err := uuid.Parse(*in.OriginNodeID)
		if err != nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid originNodeId"))
			return
		}
		originNode = &on
	}
	// Serviceability check.
	version, _ := globalState.Serviceability.CurrentVersion()
	res := globalState.Serviceability.Check(c.Request.Context(), serviceabilityRequest{
		Origin:        in.Origin,
		OriginType:    defaultStr(in.OriginType, "home"),
		OriginNodeID:  in.OriginNodeID,
		SampleTypeID:  stID,
		Deadline:      deadline,
	})
	if !res.Serviceable {
