		OriginType:      defaultStr(in.OriginType, "home"),
		OriginNodeID:    originNode,
		Earliest:        earliest,
		Latest:          latest,
		Deadline:        deadline,
	})
	if apierr.HTTPStatus != 0 {
		auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "plan_failed", "sample", sampleID.String(), false, map[string]any{"reason": apierr.Code})
		WriteError(c, apierr)
