		// grab journey id from the first leg.
		_ = journeyID
	}
	// The planOutput contains the inserted ids; we look up the journey id.
	var jID uuid.UUID
	_ = globalState.PG.QueryRow(c.Request.Context(), `
		SELECT journey_id FROM assignments WHERE assignment_id=$1 LIMIT 1
	`, plan.Legs[0]["assignmentId"]).Scan(&jID)
	_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sampleID, jID)
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "create_collection_request", "request", requestID.String(), true, map[string]any{
		"sampleId": sampleID.String(),
	})
	resp := gin.H{
		"requestId":   requestID,
		"sampleId":    sampleID,
		"journeyId":   jID,
		"sampleTypeId": stID,
		"status":      "pending",
	}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	globalState.Realtime.Emit(c.Request.Context(), "request_created", "request", requestID.String(), map[string]any{
		"sampleId": sampleID.String(),
	})
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

