package api

import (
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// handleAcceptAssignment accepts an offered assignment.
func handleAcceptAssignment(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	id, err := uuid.Parse(in.AssignmentID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignmentId"))
		return
	}
	a, apierr := loadAssignment(c.Request.Context(), id)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID != nil && *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "already_assigned", "assignment already claimed"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE assignments SET worker_id=$2, status='accepted', accepted_at=NOW() WHERE assignment_id=$1`, id, sess.UserID)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	// If this is a collection assignment, transfer holder.
	if a.SampleID != nil {
		_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE samples SET current_holder_id=$2 WHERE sample_id=$1`, a.SampleID, sess.UserID)
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "accept_assignment", "assignment", id.String(), true, nil)
	globalState.Realtime.Emit(c.Request.Context(), "assignment_accepted", "assignment", id.String(), map[string]any{"workerId": sess.UserID})
	resp := gin.H{"assignmentId": id, "status": "accepted"}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleDeclineAssignment declines an offered assignment.
func handleDeclineAssignment(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	id, err := uuid.Parse(in.AssignmentID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignmentId"))
		return
	}
	a, apierr := loadAssignment(c.Request.Context(), id)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID != nil && *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "not_your_assignment", "not offered to you"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE assignments SET status='declined', declined_at=NOW(), decline_reason=$2 WHERE assignment_id=$1`, id, in.Reason)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE users SET decline_count=decline_count+1 WHERE user_id=$1`, sess.UserID)
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "decline_assignment", "assignment", id.String(), true, map[string]any{"reason": in.Reason})
	globalState.Realtime.Emit(c.Request.Context(), "assignment_declined", "assignment", id.String(), map[string]any{"reason": in.Reason})
	// Re-offer to next eligible worker via the planner.
	reofferAssignment(c.Request.Context(), id, a)
	resp := gin.H{"assignmentId": id, "status": "declined"}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleUpdateAssignmentProgress records a status update.
func handleUpdateAssignmentProgress(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	id, err := uuid.Parse(in.AssignmentID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignmentId"))
		return
	}
	occurred, _ := time.Parse(time.RFC3339Nano, in.OccurredAt)
	a, apierr := loadAssignment(c.Request.Context(), id)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID == nil || *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "not_your_assignment", "not your assignment"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE assignments SET status=$2, completed_at=CASE WHEN $2 IN ('completed','delivered','arrived') THEN COALESCE(occurred_at,$3) END, occurred_at=$3 WHERE assignment_id=$1`, id, in.Status, occurred)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", id.String(), true, map[string]any{"status": in.Status})
	globalState.Realtime.Emit(c.Request.Context(), "assignment_progress", "assignment", id.String(), map[string]any{"status": in.Status})
	resp := gin.H{"assignmentId": id, "status": in.Status}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleRecordWorkerLocation records a location update for the current worker.
func handleRecordWorkerLocation(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		AssignmentID string `json:"assignmentId"`
		Coordinate   coord  `json:"coordinate"`
		Sequence     int    `json:"sequence"`
		RecordedAt   string `json:"recordedAt"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	id, err := uuid.Parse(in.AssignmentID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignmentId"))
		return
	}
	recorded, _ := time.Parse(time.RFC3339Nano, in.RecordedAt)
	a, apierr := loadAssignment(c.Request.Context(), id)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID == nil || *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "not_your_assignment", "not your assignment"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)
	`, sess.UserID, id, in.Coordinate.Latitude, in.Coordinate.Longitude, in.Sequence, recorded)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	// If sample present, also update latest location for staleness display.
	if a.SampleID != nil {
		_, _ = globalState.PG.Exec(c.Request.Context(), `
			UPDATE samples SET location_latitude=$2, location_longitude=$3, location_recorded_at=$4 WHERE sample_id=$1
		`, a.SampleID, in.Coordinate.Latitude, in.Coordinate.Longitude, recorded)
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "record_worker_location", "worker", sess.UserID.String(), true, map[string]any{
		"assignmentId": id.String(), "sequence": in.Sequence,
	})
	globalState.Realtime.Emit(c.Request.Context(), "worker_location", "worker", sess.UserID.String(), map[string]any{
		"latitude": in.Coordinate.Latitude, "longitude": in.Coordinate.Longitude, "recordedAt": recorded,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"assignmentId": id, "sequence": in.Sequence, "recordedAt": recorded.Format(time.RFC3339Nano)}})
}

// reofferAssignment picks another qualified worker and re-offers.
func reofferAssignment(ctx interface{ Done() <-chan struct{} }, id uuid.UUID, a assignment) {
	// Try to find a different worker for the same role.
	var role string
	switch a.Kind {
	case "collection":
		role = "collection_professional"
	case "transport":
		role = "delivery_partner"
	case "node":
		role = "node_handler"
	case "laboratory":
		role = "laboratory_team"
	}
	if role == "" {
		return
	}
	rows, err := globalState.PG.Query(castCtx(ctx), `
		SELECT user_id FROM users
		WHERE active=TRUE AND available=TRUE AND $1 = ANY(roles)
		  AND (decline_count < 3)
		  AND user_id NOT IN (SELECT worker_id FROM assignments WHERE assignment_id=$2 AND worker_id IS NOT NULL)
		ORDER BY decline_count ASC, (SELECT COUNT(*) FROM assignments WHERE worker_id=users.user_id AND status IN ('pending','accepted','in_progress')) ASC
		LIMIT 1
	`, role, id)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var w uuid.UUID
		if err := rows.Scan(&w); err == nil {
			_, _ = globalState.PG.Exec(castCtx(ctx), `UPDATE assignments SET worker_id=$2, status='pending' WHERE assignment_id=$1`, id, w)
			globalState.Realtime.Emit(castCtx(ctx), "assignment_offered", "assignment", id.String(), map[string]any{"workerId": w})
		}
	}
}

func castCtx(ctx interface{}) (out interface {
	Deadline() (time.Time, bool)
	Done() <-chan struct{}
	Err() error
	Value(any) any
}) {
	// We expect *gin.Context from the caller, but the helper takes interface{} for testability.
	type ctxIface interface {
		Deadline() (time.Time, bool)
		Done() <-chan struct{}
		Err() error
		Value(any) any
	}
	if v, ok := ctx.(ctxIface); ok {
		return v
	}
	// Last resort: pass nil; queries will fail and be ignored.
	return nil
}

var _ = pgx.ErrNoRows
var _ = errors.New

