package api

import (
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// handleCollectAndSealSample seals the sample on collection.
func handleCollectAndSealSample(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		SampleID         string  `json:"sampleId"`
		AssignmentID     string  `json:"assignmentId"`
		CollectedAt      string  `json:"collectedAt"`
		ContainerType    string  `json:"containerType"`
		ObservedTempC    float64 `json:"observedTemperatureC"`
		IdempotencyKey   string  `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	sid, err := uuid.Parse(in.SampleID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleId"))
		return
	}
	aid, err := uuid.Parse(in.AssignmentID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignmentId"))
		return
	}
	collectedAt, _ := time.Parse(time.RFC3339Nano, in.CollectedAt)
	a, apierr := loadAssignment(c.Request.Context(), aid)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID == nil || *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "not_your_assignment", "not your assignment"))
		return
	}
	// Lookup sample temperature window.
	var minC, maxC float64
	var sampleTypeID uuid.UUID
	var name string
	if err := globalState.PG.QueryRow(c.Request.Context(), `
		SELECT s.temperature_min_c, s.temperature_max_c, s.sample_type_id, st.name
		FROM samples s JOIN sample_types st ON st.sample_type_id = s.sample_type_id
		WHERE s.sample_id = $1
	`, sid).Scan(&minC, &maxC, &sampleTypeID, &name); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			WriteError(c, Err(http.StatusNotFound, "not_found", "sample not found"))
			return
		}
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	exception := in.ObservedTempC < minC || in.ObservedTempC > maxC
	if in.ContainerType == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "containerType required"))
		return
	}
	tx, err := globalState.PG.Begin(c.Request.Context())
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	defer tx.Rollback(c.Request.Context())
	_, err = tx.Exec(c.Request.Context(), `
		UPDATE samples SET sealed=TRUE, sealed_at=$2, container_type=$3, current_holder_id=$4, status='sealed', collected_at=$2, location_recorded_at=$2
		WHERE sample_id=$1
	`, sid, collectedAt, in.ContainerType, sess.UserID)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	_, err = tx.Exec(c.Request.Context(), `UPDATE assignments SET status='completed', completed_at=$2 WHERE assignment_id=$1`, aid, collectedAt)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	if exception {
		_, _ = tx.Exec(c.Request.Context(), `
			INSERT INTO sample_exceptions (sample_id, reason, observed_at) VALUES ($1, 'handling_temperature_out_of_range', $2)
		`, sid, collectedAt)
	}
	if err := tx.Commit(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", sid.String(), true, map[string]any{
		"assignmentId": aid.String(), "containerType": in.ContainerType, "temperatureC": in.ObservedTempC, "exception": exception,
	})
	globalState.Realtime.Emit(c.Request.Context(), "sample_sealed", "sample", sid.String(), map[string]any{"workerId": sess.UserID})
	resp := gin.H{"sampleId": sid, "sealed": true, "exception": exception}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleRecordHandlingCheckpoint records an in-transit checkpoint.
func handleRecordHandlingCheckpoint(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		SampleID         string  `json:"sampleId"`
		AssignmentID     string  `json:"assignmentId"`
		LocationID       *string `json:"locationId"`
		ContainerType    string  `json:"containerType"`
		ObservedTempC    float64 `json:"observedTemperatureC"`
		RecordedAt       string  `json:"recordedAt"`
		IdempotencyKey   string  `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	sid, err := uuid.Parse(in.SampleID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleId"))
		return
	}
	recorded, _ := time.Parse(time.RFC3339Nano, in.RecordedAt)
	var minC, maxC float64
	if err := globalState.PG.QueryRow(c.Request.Context(), `SELECT temperature_min_c, temperature_max_c FROM samples WHERE sample_id=$1`, sid).Scan(&minC, &maxC); err != nil {
		WriteError(c, Err(http.StatusNotFound, "not_found", "sample not found"))
		return
	}
	exception := in.ObservedTempC < minC || in.ObservedTempC > maxC
	if exception {
		_, _ = globalState.PG.Exec(c.Request.Context(), `
			INSERT INTO sample_exceptions (sample_id, reason, observed_at) VALUES ($1, 'handling_temperature_out_of_range', $2)
		`, sid, recorded)
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "record_handling_checkpoint", "sample", sid.String(), true, map[string]any{
		"containerType": in.ContainerType, "temperatureC": in.ObservedTempC, "exception": exception,
	})
	resp := gin.H{"sampleId": sid, "exception": exception, "recordedAt": recorded.Format(time.RFC3339Nano)}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleInitiateHandoff records the sender-side intent to hand off a sample.
func handleInitiateHandoff(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		SampleID       string `json:"sampleId"`
		FromAssignment string `json:"fromAssignmentId"`
		ToAssignment   string `json:"toAssignmentId"`
		ReceiverID     string `json:"receiverId"`
		InitiatedAt    string `json:"initiatedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	sid, err := uuid.Parse(in.SampleID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleId"))
		return
	}
	fromAid, err := uuid.Parse(in.FromAssignment)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid fromAssignmentId"))
		return
	}
	toAid, err := uuid.Parse(in.ToAssignment)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid toAssignmentId"))
		return
	}
	recv, err := uuid.Parse(in.ReceiverID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid receiverId"))
		return
	}
	a, apierr := loadAssignment(c.Request.Context(), fromAid)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID == nil || *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "not_your_assignment", "not your assignment"))
		return
	}
	id := uuid.New()
	_, err = globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO handoffs (handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, sender_confirmed_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7)
	`, id, sid, fromAid, toAid, sess.UserID, recv, time.Now().UTC())
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	// Mark sample as having a pending handoff.
	_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE samples SET pending_handoff_id=$2 WHERE sample_id=$1`, sid, id)
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "initiate_handoff", "sample", sid.String(), true, map[string]any{
		"handoffId": id.String(), "from": fromAid.String(), "to": toAid.String(),
	})
	resp := gin.H{"handoffId": id, "status": "sender_confirmed"}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleConfirmHandoff completes a handoff from sender and/or receiver sides.
func handleConfirmHandoff(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	hid, err := uuid.Parse(in.HandoffID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid handoffId"))
		return
	}
	confirmed, _ := time.Parse(time.RFC3339Nano, in.ConfirmedAt)
	var senderID, receiverID, sampleID uuid.UUID
	if err := globalState.PG.QueryRow(c.Request.Context(), `
		SELECT sender_id, receiver_id, sample_id, COALESCE(receiver_confirmed_at, '0001-01-01'::timestamptz) FROM handoffs WHERE handoff_id=$1
	`, hid).Scan(&senderID, &receiverID, &sampleID, new(time.Time)); err != nil {
		WriteError(c, Err(http.StatusNotFound, "not_found", "handoff not found"))
		return
	}
	switch in.ConfirmationSide {
	case "sender":
		if senderID != sess.UserID {
			WriteError(c, Err(http.StatusConflict, "not_your_handoff", "not your handoff"))
			return
		}
		_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE handoffs SET sender_confirmed_at=$2 WHERE handoff_id=$1`, hid, confirmed)
	case "receiver":
		if receiverID != sess.UserID {
			WriteError(c, Err(http.StatusConflict, "not_your_handoff", "not your handoff"))
			return
		}
		_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE handoffs SET receiver_confirmed_at=$2 WHERE handoff_id=$1`, hid, confirmed)
	default:
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "confirmationSide must be sender or receiver"))
		return
	}
	// Check if both confirmed.
	var sConf, rConf *time.Time
	_ = globalState.PG.QueryRow(c.Request.Context(), `SELECT sender_confirmed_at, receiver_confirmed_at FROM handoffs WHERE handoff_id=$1`, hid).Scan(&sConf, &rConf)
	complete := sConf != nil && rConf != nil
	if complete {
		_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE samples SET current_holder_id=$2, pending_handoff_id=NULL WHERE sample_id=$1`, sampleID, receiverID)
		// Mark the receiver assignment as in_progress.
		var toAid uuid.UUID
		_ = globalState.PG.QueryRow(c.Request.Context(), `SELECT to_assignment_id FROM handoffs WHERE handoff_id=$1`, hid).Scan(&toAid)
		if toAid != uuid.Nil {
			_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE assignments SET status='in_progress' WHERE assignment_id=$1`, toAid)
		}
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "confirm_handoff", "sample", sampleID.String(), true, map[string]any{
		"side": in.ConfirmationSide, "complete": complete,
	})
	resp := gin.H{"handoffId": hid, "complete": complete}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleConfirmLaboratoryReceipt confirms that a laboratory received a sample.
func handleConfirmLaboratoryReceipt(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		SampleID         string `json:"sampleId"`
		LaboratoryID     string `json:"laboratoryId"`
		ReceivedAt       string `json:"receivedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	sid, err := uuid.Parse(in.SampleID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleId"))
		return
	}
	lab, err := uuid.Parse(in.LaboratoryID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid laboratoryId"))
		return
	}
	receivedAt, _ := time.Parse(time.RFC3339Nano, in.ReceivedAt)
	_, err = globalState.PG.Exec(c.Request.Context(), `
		UPDATE samples SET status='received', received_lab_id=$2, received_at=$3, current_holder_id=$4 WHERE sample_id=$1
	`, sid, lab, receivedAt, sess.UserID)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "confirm_laboratory_receipt", "sample", sid.String(), true, map[string]any{
		"laboratoryId": lab.String(),
	})
	globalState.Realtime.Emit(c.Request.Context(), "sample_received", "sample", sid.String(), map[string]any{"laboratoryId": lab.String()})
	resp := gin.H{"sampleId": sid, "received": true}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleRecordLaboratoryException flags a sample as undeliverable at the lab.
func handleRecordLaboratoryException(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		SampleID         string `json:"sampleId"`
		LaboratoryID     string `json:"laboratoryId"`
		Reason           string `json:"reason"`
		ObservedAt       string `json:"observedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	sid, err := uuid.Parse(in.SampleID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleId"))
		return
	}
	lab, err := uuid.Parse(in.LaboratoryID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid laboratoryId"))
		return
	}
	obsAt, _ := time.Parse(time.RFC3339Nano, in.ObservedAt)
	_, err = globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO sample_exceptions (sample_id, reason, observed_at, location_id) VALUES ($1, $2, $3, $4)
	`, sid, in.Reason, obsAt, lab)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE samples SET status='exception' WHERE sample_id=$1`, sid)
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "record_laboratory_exception", "sample", sid.String(), true, map[string]any{
		"reason": in.Reason, "laboratoryId": lab.String(),
	})
	globalState.Realtime.Emit(c.Request.Context(), "sample_exception", "sample", sid.String(), map[string]any{"reason": in.Reason})
	resp := gin.H{"sampleId": sid, "exception": true}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

var _ = pgx.ErrNoRows

