// handleInitiateHandoff records the sender-side intent to hand off a sample.
func handleInitiateHandoff(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		SampleID       string `json:"sampleId"`
		FromAssignment string `json:"fromAssignmentId"`
		ToAssignment   string `json:"toAssignmentId"`
		ReceiverID     string `json:"receiverId"`
		InitiatedAt    string `json:"initiatedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	sid, err := uuid.Parse(in.SampleID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleId"))
		return
	}
	fromAid, err := uuid.Parse(in.FromAssignment)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid fromAssignmentId"))
		return
	}
	toAid, err := uuid.Parse(in.ToAssignment)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid toAssignmentId"))
		return
	}
	recv, err := uuid.Parse(in.ReceiverID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid receiverId"))
		return
	}
	a, apierr := loadAssignment(c.Request.Context(), fromAid)
