			capUnits, resUnits, cooledCap, cooledRes                                 int
		)
		_ = sampleTypes
		if err := rows3.Scan(&id, &name, &lat, &lon, &active, &cov, &handling, &fnsRaw, &capUnits, &resUnits, &cooledCap, &cooledRes); err == nil {
			// accepted sample types
			row := globalState.PG.QueryRow(ctx, `SELECT COALESCE(array_agg(sample_type_id::text), '{}') FROM laboratory_acceptance WHERE location_id=$1 AND accepts=TRUE`, id)
			_ = row.Scan(&sampleTypes)
			var fmap map[string]bool
			decodeJSON(fnsRaw, &fmap)
			locations = append(locations, gin.H{
