// handleReportDisruption records a network/resource disruption.
func handleReportDisruption(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	occurred, _ := time.Parse(time.RFC3339Nano, in.OccurredAt)
	allowed := map[string]bool{
		"location": true, "node": true, "laboratory": true,
		"connection": true, "route": true, "worker": true, "capacity": true,
	}
	if !allowed[in.ResourceType] {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "unknown resourceType"))
		return
	}
	// Deactivate resource.
	switch in.ResourceType {
	case "location", "node":
		if id, err := uuid.Parse(in.ResourceID); err == nil {
			_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE locations SET active=FALSE, updated_at=NOW() WHERE location_id=$1`, id)
		}
	case "connection":
		if id, err := uuid.Parse(in.ResourceID); err == nil {
			_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE connections SET active=FALSE WHERE connection_id=$1`, id)
		}
	case "worker":
		if id, err := uuid.Parse(in.ResourceID); err == nil {
			_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE users SET active=FALSE, available=FALSE WHERE user_id=$1`, id)
		}
	case "capacity":
		// noop
	case "laboratory":
		if id, err := uuid.Parse(in.ResourceID); err == nil {
			_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE locations SET active=FALSE, updated_at=NOW() WHERE location_id=$1`, id)
		}
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "report_disruption", in.ResourceType, in.ResourceID, true, map[string]any{"reason": in.Reason})
	if _, err := globalState.Serviceability.Recompute(c.Request.Context()); err != nil {
		// continue; not fatal
	}
	resp := gin.H{"resourceType": in.ResourceType, "resourceId": in.ResourceID, "occurredAt": occurred.Format(time.RFC3339Nano)}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}"}

