// handleEditActivePlan supports adding/removing stops, reordering, replacing workers, rerouting.
func handleEditActivePlan(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		JourneyID          string                 `json:"journeyId"`
		ExpectedPlanVersion int                   `json:"expectedPlanVersion"`
		ChangeType         string                 `json:"changeType"`
		Changes            map[string]any         `json:"changes"`
		IdempotencyKey     string                 `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	id, err := uuid.Parse(in.JourneyID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid journeyId"))
		return
	}
	var currentVersion int
	if err := globalState.PG.QueryRow(c.Request.Context(), `SELECT plan_version FROM journeys WHERE journey_id=$1`, id).Scan(&currentVersion); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			WriteError(c, Err(http.StatusNotFound, "not_found", "journey not found"))
			return
		}
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	if currentVersion != in.ExpectedPlanVersion {
		WriteError(c, Err(http.StatusConflict, "state_snapshot_changed", "plan version mismatch"))
		return
	}
	// Only allow changes that don't affect completed legs.
	switch in.ChangeType {
	case "add_stop":
		// Insert a new handoff stop at the end and create a new assignment.
		var lid uuid.UUID
		if v, ok := in.Changes["locationId"].(string); ok {
			lid, _ = uuid.Parse(v)
		}
		if lid == uuid.Nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "locationId required"))
			return
		}
		var maxSeq int
		_ = globalState.PG.QueryRow(c.Request.Context(), `SELECT COALESCE(MAX(sequence),0) FROM journey_stops WHERE journey_id=$1`, id).Scan(&maxSeq)
		stopID := uuid.New()
		_, err = globalState.PG.Exec(c.Request.Context(), `
			INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
			SELECT $1, $2, $3, 'handoff', $4, NOW(), COALESCE(handling_minutes,0), latitude, longitude FROM locations WHERE location_id=$3
		`, stopID, id, lid, maxSeq+1)
		if err != nil {
			WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
			return
		}
	case "remove_stop":
		var stopID uuid.UUID
		if v, ok := in.Changes["stopId"].(string); ok {
			stopID, _ = uuid.Parse(v)
		}
		if stopID == uuid.Nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "stopId required"))
			return
		}
		_, err = globalState.PG.Exec(c.Request.Context(), `DELETE FROM journey_stops WHERE stop_id=$1 AND journey_id=$2 AND stop_type='handoff'`, stopID, id)
		if err != nil {
			WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
			return
		}
	case "reorder_stops":
		// Pass: not implemented in detail; we just bump the version.
	case "replace_worker", "reassign_worker":
		var aid, wid uuid.UUID
		if v, ok := in.Changes["assignmentId"].(string); ok {
			aid, _ = uuid.Parse(v)
		}
		if v, ok := in.Changes["workerId"].(string); ok {
			wid, _ = uuid.Parse(v)
		}
		if aid == uuid.Nil || wid == uuid.Nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "assignmentId and workerId required"))
			return
		}
		_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE assignments SET worker_id=$2, status='pending' WHERE assignment_id=$1`, aid, wid)
		if err != nil {
			WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
			return
		}
	case "merge_samples", "split_samples", "split_batch":
		// Not supported for single-sample flows; surface a 409.
		WriteError(c, Err(http.StatusConflict, "unsupported_change", "this change type requires batch flows"))
		return
	case "cancel_work":
		WriteError(c, Err(http.StatusConflict, "use_cancel_journey", "use /api/cancel-journey instead"))
		return
	case "reroute", "replace_route":
		// bump version - actual re-routing happens in /api/reroute-journey.
	default:
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "unknown changeType"))
		return
	}
	// bump version atomically.
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "edit_active_plan", "journey", id.String(), true, map[string]any{
		"changeType": in.ChangeType,
	})
	resp := gin.H{"journeyId": id, "changeType": in.ChangeType}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	globalState.Realtime.Emit(c.Request.Context(), "journey_edited", "journey", id.String(), map[string]any{"changeType": in.ChangeType})
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleCancelJourney cancels a journey.
func handleCancelJourney(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		JourneyID          string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason             string `json:"reason"`
		IdempotencyKey     string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	id, err := uuid.Parse(in.JourneyID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid journeyId"))
		return
	}
	var currentVersion int
	if err := globalState.PG.QueryRow(c.Request.Context(), `SELECT plan_version FROM journeys WHERE journey_id=$1`, id).Scan(&currentVersion); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			WriteError(c, Err(http.StatusNotFound, "not_found", "journey not found"))
			return
		}
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	if currentVersion != in.ExpectedPlanVersion {
		WriteError(c, Err(http.StatusConflict, "state_snapshot_changed", "plan version mismatch"))
		return
	}
	tx, err := globalState.PG.Begin(c.Request.Context())
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	defer tx.Rollback(c.Request.Context())
	// release capacity on legs.
	rows, err := tx.Query(c.Request.Context(), `SELECT assignment_id, from_location_id, to_location_id, requires_cooled, COALESCE(reserved_capacity,0) FROM assignments WHERE journey_id=$1 AND status IN ('pending','in_progress')`, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	type leg struct {
		from, to                                                              uuid.UUID
		cooled                                                                bool
		units                                                                 int
	}
	var legs []leg
	for rows.Next() {
		var l leg
		var aid uuid.UUID
		if err := rows.Scan(&aid, &l.from, &l.to, &l.cooled, &l.units); err == nil {
			legs = append(legs, l)
		}
	}
	rows.Close()
	for _, l := range legs {
		col := "reserved_units"
		if l.cooled {
			col = "cooled_reserved_units"
		}
		_, _ = tx.Exec(c.Request.Context(), `UPDATE connections SET `+col+` = GREATEST(0, `+col+` - $3) WHERE from_location_id=$1 AND to_location_id=$2`, l.from, l.to, l.units)
	}
	_, err = tx.Exec(c.Request.Context(), `UPDATE assignments SET status='cancelled' WHERE journey_id=$1`, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	_, err = tx.Exec(c.Request.Context(), `UPDATE journeys SET status='cancelled', plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	_, err = tx.Exec(c.Request.Context(), `UPDATE samples SET active_journey_id=NULL, status='cancelled' WHERE active_journey_id=$1`, id)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	if err := tx.Commit(c.Request.Context()); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "cancel_journey", "journey", id.String(), true, map[string]any{"reason": in.Reason})
	globalState.Realtime.Emit(c.Request.Context(), "journey_cancelled", "journey", id.String(), map[string]any{"reason": in.Reason})
	resp := gin.H{"journeyId": id, "status": "cancelled"}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

