// handleSearchAuditTrail performs a paginated search over the audit log.
func handleSearchAuditTrail(c *gin.Context) {
	sess := currentSession(c)
	if sess.ActiveRole != "administrator" && sess.ActiveRole != "dispatcher" {
		WriteError(c, Err(http.StatusForbidden, "role_not_held", "dispatcher/admin only"))
		return
	}
	var in struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Limit <= 0 || in.Limit > 5000 {
		in.Limit = 500
	}
	if in.Offset < 0 {
		in.Offset = 0
	}
	if in.Order == "" {
		in.Order = "newest_first"
	}
	filter := map[string]any{
		"query":      in.Query,
		"actorId":    in.ActorID,
		"entityType": in.EntityType,
		"entityId":   in.EntityID,
		"action":     in.Action,
		"role":       in.Role,
		"success":    in.Success,
		"fromTime":   in.FromTime,
		"toTime":     in.ToTime,
		"limit":      in.Limit,
		"offset":     in.Offset,
		"order":      in.Order,
	}
	entries, total := globalState.Audit.SearchPaged(c.Request.Context(), filter)
	resp := gin.H{
		"entries": entries,
		"total":   total,
		"returned": len(entries),
		"offset":   in.Offset,
		"limit":    in.Limit,
		"order":    in.Order,
		"hasMore":  in.Offset+len(entries) < total,
	}
	if resp["hasMore"].(bool) {
		resp["nextOffset"] = in.Offset + len(entries)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleEvents streams realtime events. The contract exposes only the polling
// fallback here; websockets are upgraded separately.
func handleEvents(c *gin.Context) {
	since := int64(0)
	if v := c.Query("since"); v != "" {
		_, _ = parseInt(v, &since)
	}
	events := globalState.Realtime.Recent(since, 200)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"events": events,
		"cursor": globalState.Realtime.Cursor(),
	}})
}

func parseInt(s string, dst *int64) (int64, error) {
	var v int64
	var err error
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, nil
		}
		v = v*10 + int64(c-'0')
	}
	*dst = v
	return v, err
}

