package api

import (
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
)

// handleReadServiceabilitySnapshot returns the latest complete snapshot.
func handleReadServiceabilitySnapshot(c *gin.Context) {
	snap, version, computedAt := globalState.Serviceability.Snapshot(c.Request.Context())
	regions := []gin.H{}
	for _, r := range snap {
		regions = append(regions, gin.H{
			"locationId": r.ID,
			"name":       r.Name,
			"latitude":   r.Latitude,
			"longitude":  r.Longitude,
			"coverageKm": r.CoverageKm,
		})
	}
	activeCount := 0
	for _, r := range snap {
		if r.Active {
			activeCount++
		}
	}
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"version":                   version,
		"status":                    "complete",
		"computedAt":                computedAt.Format(time.RFC3339Nano),
		"networkRevision":           globalState.Serviceability.NetworkRevision(),
		"regions":                   regions,
		"activeCollectionPointCount": activeCount,
	}})
	_ = http.StatusOK
}

