// handleCheckServiceability runs a dry-run serviceability check.
func handleCheckServiceability(c *gin.Context) {
	_ = currentSession(c)
	var in struct {
		Origin             coord    `json:"origin"`
		OriginType         string   `json:"originType"`
		OriginNodeID       *string  `json:"originNodeId"`
		SampleTypeID       string   `json:"sampleTypeId"`
		RequestedAt        string   `json:"requestedAt"`
		DeliveryDeadline   string   `json:"deliveryDeadline"`
		EarliestCollection *string  `json:"earliestCollectionAt"`
		LatestCollection   *string  `json:"latestCollectionAt"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.SampleTypeID == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "sampleTypeId required"))
