type Event struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]interface{} `json:"payload"`
	CreatedAt  time.Time              `json:"createdAt"`
}

// Hub publishes events to all connected WebSocket clients.
type Hub struct {
	mu          sync.RWMutex
	subscribers map[int64]chan Event
	nextID      int64
	pool        *pgxpool.Pool
}

func NewHub() *Hub {
	return &Hub{subscribers: map[int64]chan Event{}}
}

// AttachPool wires the hub into Postgres so event streams are persisted.
func (h *Hub) AttachPool(p *pgxpool.Pool) { h.pool = p }

// Subscribe returns an event channel and a unique subscriber id used for Unsubscribe.
func (h *Hub) Subscribe(buf int) (int64, <-chan Event) {
	ch := make(chan Event, buf)
	h.mu.Lock()
	h.nextID++
	id := h.nextID
	h.subscribers[id] = ch
	h.mu.Unlock()
	return id, ch
}

func (h *Hub) Unsubscribe(id int64) {
	h.mu.Lock()
	ch, ok := h.subscribers[id]
	if ok {
		delete(h.subscribers, id)
	}
	h.mu.Unlock()
	if ok {
		close(ch)
	}
}

func (h *Hub) Publish(ctx context.Context, e Event) {
	if h.pool != nil {
		row := h.pool.QueryRow(ctx, `
			INSERT INTO realtime_events (event_type, entity_type, entity_id, payload)
			VALUES ($1, $2, $3, $4::jsonb) RETURNING id, created_at
		`, e.Type, e.EntityType, e.EntityID, mustJSON(e.Payload))
		if err := row.Scan(&e.ID, &e.CreatedAt); err != nil {
			log.Printf("realtime insert: %v", err)
		}
	}
	h.mu.RLock()
	defer h.mu.RUnlock()
	for _, sub := range h.subscribers {
		select {
		case sub <- e:
		default:
			// drop on slow consumer
		}
	}
}

func mustJSON(v map[string]interface{}) string {
	if v == nil {
		v = map[string]interface{}{}
	}
	b, _ := json.Marshal(v)
	return string(b)
}

type Sink struct {
	hub *Hub
}

func NewSink(h *Hub) *Sink { return &Sink{hub: h} }

func (s *Sink) Emit(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	if s == nil || s.hub == nil {
		return
	}
	s.hub.Publish(ctx, Event{
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now().UTC(),
	})
}

