package api

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// handleAcceptAssignment accepts an offered assignment.
func handleAcceptAssignment(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	id, err := uuid.Parse(in.AssignmentID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignmentId"))
		return
	}
	a, apierr := loadAssignment(c.Request.Context(), id)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	if a.WorkerID != nil && *a.WorkerID != sess.UserID {
		WriteError(c, Err(http.StatusConflict, "already_assigned", "assignment already claimed"))
		return
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `UPDATE assignments SET worker_id=$2, status='accepted', accepted_at=NOW() WHERE assignment_id=$1`, id, sess.UserID)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	if a.SampleID != nil {
		_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE samples SET current_holder_id=$2 WHERE sample_id=$1`, a.SampleID, sess.UserID)
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "accept_assignment", "assignment", id.String(), true, nil)
	globalState.Realtime.Emit(c.Request.Context(), "assignment_accepted", "assignment", id.String(), map[string]any{"workerId": sess.UserID})
	resp := gin.H{"assignmentId": id, "status": "accepted"}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleDeclineAssignment declines an offered assignment.
func handleDeclineAssignment(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
