		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Limit <= 0 || in.Limit > 5000 {
		in.Limit = 500
	}
	if in.Offset < 0 {
		in.Offset = 0
	}
	if in.Order == "" {
		in.Order = "newest_first"
	}
	filter := map[string]any{
		"query":      in.Query,
		"actorId":    in.ActorID,
		"entityType": in.EntityType,
		"entityId":   in.EntityID,
		"action":     in.Action,
		"role":       in.Role,
		"success":    in.Success,
		"fromTime":   in.FromTime,
		"toTime":     in.ToTime,
		"limit":      in.Limit,
		"offset":     in.Offset,
		"order":      in.Order,
	}
	entries, total, _ := globalState.Audit.SearchPaged(c.Request.Context(), filter)
	resp := gin.H{
		"entries": entries,
		"total":   total,
		"returned": len(entries),
		"offset":   in.Offset,
		"limit":    in.Limit,
		"order":    in.Order,
		"hasMore":  in.Offset+len(entries) < total,
	}
	if resp["hasMore"].(bool) {
		resp["nextOffset"] = in.Offset + len(entries)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

// handleEvents streams realtime events. The contract exposes only the polling
// fallback here; websockets are upgraded separately.
func handleEvents(c *gin.Context) {
	since := int64(0)
	if v := c.Query("since"); v != "" {
		_, _ = parseInt(v, &since)
	}
	var sinceTime time.Time
	if since > 0 {
		sinceTime = time.Unix(since, 0).UTC()
	}
	events := globalState.Realtime.Recent(sinceTime, 200)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"events": events,
		"cursor": globalState.Realtime.Cursor(),
	}})
}

func parseInt(s string, dst *int64) (int64, error) {
	var v int64
	var err error
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, nil
		}
		v = v*10 + int64(c-'0')
	}
	*dst = v
	return v, err
}

