func defaultStr(s, def string) string {
	if s == "" {
		return def
	}
	return s
}

func orDefault(s, def string) string {
	if s == "" {
		return def
	}
	return s
}

func buildSampleState(ctx context.Context, id uuid.UUID, sess *auth.Session) (gin.H, APIError) {
	row := globalState.PG.QueryRow(ctx, `
		SELECT sample_id, request_id, requester_id, sample_type_id, origin_type, latitude, longitude,
		       requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		       container_type, temperature_min_c, temperature_max_c, COALESCE(incompatible_sample_types,'{}'),
		       active_journey_id, current_holder_id, target_lab_id, status, sealed, location_recorded_at, location_latitude, location_longitude
		FROM samples WHERE sample_id=$1
	`, id)
	var s store.Sample
	var originType, status string
	var inc []string
	var activeJ, currentHolder, targetLab *uuid.UUID
	var latRecAt *time.Time
	var latRec, lonRec *float64
	if err := row.Scan(&s.SampleID, &s.RequestID, &s.RequesterID, &s.SampleTypeID, &originType, &s.Origin.Latitude, &s.Origin.Longitude,
		&s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
		&s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &inc,
		&activeJ, &currentHolder, &targetLab, &status, &s.Sealed, &latRecAt, &latRec, &lonRec); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, Err(http.StatusNotFound, "not_found", "sample not found")
		}
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	if sess != nil {
		role := sess.ActiveRole
		if role != "administrator" && role != "dispatcher" && role != "requester" {
			return nil, Err(http.StatusForbidden, "role_not_held", "lifecycle is dispatcher-only")
		}
		if role == "requester" && sess.UserID != s.RequesterID {
			return nil, Err(http.StatusForbidden, "not_your_sample", "not your sample")
		}
	}
	// Build timeline
	var tl []map[string]any
	if globalState.Audit != nil {
		entries, _ := globalState.Audit.Search(ctx, map[string]any{"entityType": "sample", "entityId": id.String(), "limit": 500, "order": "newest_first"})
		for _, e := range entries {
			tl = append(tl, map[string]any{
				"eventId": e.EventID, "action": e.Action, "actorId": ptrString(e.ActorID), "role": e.Role,
				"entityType": e.EntityType, "entityId": e.EntityID, "success": e.Success,
				"occurredAt": e.OccurredAt.Format(time.RFC3339Nano), "details": e.Details,
			})
		}
	}
	state := gin.H{
		"sampleId": s.SampleID, "requestId": s.RequestID, "requesterId": s.RequesterID,
		"origin": gin.H{"latitude": s.Origin.Latitude, "longitude": s.Origin.Longitude},
		"originType": originType,
		"requestedAt": s.RequestedAt.Format(time.RFC3339Nano),
		"deliveryDeadline": s.DeliveryDeadline.Format(time.RFC3339Nano),
		"sampleTypeId": s.SampleTypeID,
		"containerType": s.ContainerType,
		"temperatureMinC": s.TemperatureMinC,
		"temperatureMaxC": s.TemperatureMaxC,
		"incompatibleSampleTypes": inc,
		"serviceability": "serviceable",
		"activeAssignmentIds": []uuid.UUID{},
		"state": gin.H{"status": status},
		"timeline": tl,
		"locationStale": isStale(latRecAt),
	}
	if activeJ != nil {
		state["activeJourneyId"] = activeJ
	}
	if currentHolder != nil {
		state["currentHolderId"] = currentHolder
	}
	if targetLab != nil {
		state["targetLaboratoryId"] = targetLab
	}
	if latRec != nil && lonRec != nil {
		state["latestLocation"] = gin.H{"latitude": *latRec, "longitude": *lonRec}
	}
	if latRecAt != nil {
		state["locationRecordedAt"] = latRecAt.Format(time.RFC3339Nano)
	}
	// Populate activeAssignmentIds.
	rows, _ := globalState.PG.Query(ctx, `SELECT assignment_id FROM assignments WHERE journey_id=$1 AND status IN ('pending','in_progress')`, activeJ)
	for rows.Next() {
		var aid uuid.UUID
		if err := rows.Scan(&aid); err == nil {
			state["activeAssignmentIds"] = append(state["activeAssignmentIds"].([]uuid.UUID), aid)
		}
	}
	rows.Close()
	return state, APIError{}
}

// currentSession returns the active auth.Session; defined in middleware.go.
var _ = currentSession

func ptrString(p *uuid.UUID) string {
	if p == nil {
		return ""
	}
	return p.String()
}

func isStale(t *time.Time) bool {
	if t == nil {
		return true
	}
	return time.Since(*t) > 30*time.Minute
}

func idempotencyLookup(ctx context.Context, key string) (gin.H, bool) {
	val, err := globalState.Redis.Get(ctx, "idem:"+key).Result()
	if err != nil || val == "" {
		return nil, false
	}
	var out gin.H
	if err := json.Unmarshal([]byte(val), &out); err != nil {
		return nil, false
	}
	return out, true
}

func idempotencyStore(ctx context.Context, key string, v gin.H) {
	if globalState == nil || globalState.Redis == nil {
		return
	}
	b, _ := json.Marshal(v)
	_ = globalState.Redis.Set(ctx, "idem:"+key, string(b), 24*time.Hour).Err()
}

var _ = json.Marshal

