	"labdeliver/backend/internal/auth"
	"labdeliver/backend/internal/serviceability"
	"labdeliver/backend/internal/store"
)

// serviceabilityRequest is the small input shape used by API handlers before
// converting to a full serviceability.CheckInput.
type serviceabilityRequest struct {
	Origin       coord     `json:"origin"`
	OriginType   string    `json:"originType"`
	OriginNodeID *string   `json:"originNodeId"`
	SampleTypeID uuid.UUID `json:"sampleTypeId"`
	Deadline     time.Time `json:"deliveryDeadline"`
	RequestedAt  time.Time `json:"requestedAt"`
}

func toServiceabilityInput(req serviceabilityRequest, requestedAt time.Time) serviceability.CheckInput {
	var nodeID *uuid.UUID
	if req.OriginNodeID != nil && *req.OriginNodeID != "" {
		if parsed, err := uuid.Parse(*req.OriginNodeID); err == nil {
			nodeID = &parsed
		}
	}
	return serviceability.CheckInput{
		Origin:           serviceability.Coordinate{Latitude: req.Origin.Lat, Longitude: req.Origin.Lng},
		OriginType:       req.OriginType,
		OriginNodeID:     nodeID,
		SampleTypeID:     req.SampleTypeID,
		RequestedAt:      requestedAt,
		DeliveryDeadline: req.Deadline,
	}
}

