// buildSampleLifecycle returns the dispatcher-visible SampleLifecycle payload.
// It is a richer view than SampleState and includes the full timeline, completed
// legs, active replacement plans, the pending handoff (if any) and the latest
// known location with a staleness flag.
func buildSampleLifecycle(ctx context.Context, id uuid.UUID, sess *auth.Session) (gin.H, APIError) {
	row := globalState.PG.QueryRow(ctx, `
		SELECT sample_id, request_id, requester_id, sample_type_id, origin_type, latitude, longitude,
		       requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		       container_type, temperature_min_c, temperature_max_c, COALESCE(incompatible_sample_types,'{}'),
		       active_journey_id, current_holder_id, target_lab_id, status, sealed,
		       received_laboratory_id, received_at, exception_reason,
		       latest_latitude, latest_longitude, location_recorded_at
		FROM samples WHERE sample_id=$1
	`, id)
	var s store.Sample
	var originType, status string
	var inc []string
	var activeJ, currentHolder, targetLab, recvLab *uuid.UUID
	var receivedAt *time.Time
	var excReason string
	var latRecAt *time.Time
	var latRec, lonRec *float64
	if err := row.Scan(&s.SampleID, &s.RequestID, &s.RequesterID, &s.SampleTypeID, &originType, &s.Origin.Latitude, &s.Origin.Longitude,
		&s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
		&s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &inc,
		&activeJ, &currentHolder, &targetLab, &status, &s.Sealed,
		&recvLab, &receivedAt, &excReason,
		&latRec, &lonRec, &latRecAt); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, Err(http.StatusNotFound, "not_found", "sample not found")
		}
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	if sess != nil {
		role := sess.ActiveRole
		if role != "administrator" && role != "dispatcher" {
			return nil, Err(http.StatusForbidden, "role_not_held", "lifecycle is dispatcher-only")
		}
	}
	// Timeline via audit store.
	var tl []map[string]any
	if globalState.Audit != nil {
		entries, _ := globalState.Audit.Search(ctx, map[string]any{"entityType": "sample", "entityId": id.String(), "limit": 1000, "order": "newest_first"})
		for _, e := range entries {
			tl = append(tl, map[string]any{
				"eventId":    e.EventID,
				"action":     e.Action,
				"actorId":    ptrString(e.ActorID),
				"role":       e.Role,
				"entityType": e.EntityType,
				"entityId":   e.EntityID,
				"success":    e.Success,
				"occurredAt": e.OccurredAt.Format(time.RFC3339Nano),
				"details":    e.Details,
			})
		}
	}
	out := gin.H{
		"sampleId":                s.SampleID,
		"status":                  status,
		"sealed":                  s.Sealed,
		"completedLegIds":         []uuid.UUID{},
		"activeReplacementPlanIds": []uuid.UUID{},
		"timeline":                tl,
		"locationStale":           isStale(latRecAt),
	}
	if activeJ != nil {
		out["activeJourneyId"] = activeJ
	}
	if currentHolder != nil {
		out["currentHolderId"] = currentHolder
	}
	if recvLab != nil {
		out["receivedLaboratoryId"] = recvLab
	}
	if excReason != "" {
		out["exception"] = gin.H{"reason": excReason}
	}
	if latRec != nil && lonRec != nil {
		out["latestLocation"] = gin.H{"latitude": *latRec, "longitude": *lonRec}
	}
	if latRecAt != nil {
		out["locationRecordedAt"] = latRecAt.Format(time.RFC3339Nano)
	}
	// Completed legs (assignments in 'completed' status).
	completed := []uuid.UUID{}
	if activeJ != nil {
		rows, err := globalState.PG.Query(ctx, `SELECT assignment_id FROM assignments WHERE journey_id=$1 AND status='completed'`, activeJ)
		if err == nil {
			for rows.Next() {
				var aid uuid.UUID
				if err := rows.Scan(&aid); err == nil {
					completed = append(completed, aid)
				}
			}
			rows.Close()
		}
		out["completedLegIds"] = completed
	}
	// Active replacement plan ids from disruptions table.
	plans := []uuid.UUID{}
	rows, err := globalState.PG.Query(ctx, `SELECT replacement_plan_ids FROM disruptions WHERE active=TRUE`)
	if err == nil {
		for rows.Next() {
			var ids []uuid.UUID
			if err := rows.Scan(&ids); err == nil {
				plans = append(plans, ids...)
			}
		}
		rows.Close()
	}
	out["activeReplacementPlanIds"] = plans
	// Pending handoff for this sample.
	hrow := globalState.PG.QueryRow(ctx, `
		SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id,
		       sender_id, receiver_id, sender_confirmed_at, receiver_confirmed_at,
		       status, initiated_at, confirmed_at
		FROM handoffs
		WHERE sample_id=$1 AND status='pending'
		ORDER BY initiated_at DESC LIMIT 1
	`, id)
	var h store.Handoff
	if err := hrow.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID,
		&h.SenderID, &h.ReceiverID, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt,
		&h.Status, &h.InitiatedAt, &h.ConfirmedAt); err == nil {
		out["pendingHandoffId"] = h.HandoffID
		out["pendingHandoff"] = gin.H{
			"handoffId":           h.HandoffID,
			"sampleId":            h.SampleID,
			"fromAssignmentId":    h.FromAssignmentID,
			"toAssignmentId":      h.ToAssignmentID,
			"senderId":            h.SenderID,
			"receiverId":          h.ReceiverID,
			"senderConfirmedAt":   nilOrTime(h.SenderConfirmedAt),
			"receiverConfirmedAt": nilOrTime(h.ReceiverConfirmedAt),
			"status":              h.Status,
			"initiatedAt":         h.InitiatedAt.Format(time.RFC3339Nano),
			"confirmedAt":         nilOrTime(h.ConfirmedAt),
		}
	}
	return out, APIError{}
}

func nilOrTime(t *time.Time) interface{} {
	if t == nil {
		return nil
	}
	return t.Format(time.RFC3339Nano)
}

func orDefault(s, def string) string {
	if s == "" {
		return def
	}
	return s
}

func buildSampleState(ctx context.Context, id uuid.UUID, sess *auth.Session) (gin.H, APIError) {
	row := globalState.PG.QueryRow(ctx, `
		SELECT sample_id, request_id, requester_id, sample_type_id, origin_type, latitude, longitude,
		       requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		       container_type, temperature_min_c, temperature_max_c, COALESCE(incompatible_sample_types,'{}'),
		       active_journey_id, current_holder_id, target_lab_id, status, sealed, location_recorded_at, location_latitude, location_longitude
		FROM samples WHERE sample_id=$1
	`, id)
	var s store.Sample
	var originType, status string
	var inc []string
	var activeJ, currentHolder, targetLab *uuid.UUID
	var latRecAt *time.Time
	var latRec, lonRec *float64
	if err := row.Scan(&s.SampleID, &s.RequestID, &s.RequesterID, &s.SampleTypeID, &originType, &s.Origin.Latitude, &s.Origin.Longitude,
		&s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
		&s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &inc,
		&activeJ, &currentHolder, &targetLab, &status, &s.Sealed, &latRecAt, &latRec, &lonRec); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, Err(http.StatusNotFound, "not_found", "sample not found")
		}
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	if sess != nil {
		role := sess.ActiveRole
		if role != "administrator" && role != "dispatcher" && role != "requester" {
			return nil, Err(http.StatusForbidden, "role_not_held", "lifecycle is dispatcher-only")
		}
		if role == "requester" && sess.UserID != s.RequesterID {
			return nil, Err(http.StatusForbidden, "not_your_sample", "not your sample")
		}
	}
	// Build timeline
	var tl []map[string]any
	if globalState.Audit != nil {
		entries, _ := globalState.Audit.Search(ctx, map[string]any{"entityType": "sample", "entityId": id.String(), "limit": 500, "order": "newest_first"})
		for _, e := range entries {
			tl = append(tl, map[string]any{
				"eventId": e.EventID, "action": e.Action, "actorId": ptrString(e.ActorID), "role": e.Role,
				"entityType": e.EntityType, "entityId": e.EntityID, "success": e.Success,
				"occurredAt": e.OccurredAt.Format(time.RFC3339Nano), "details": e.Details,
			})
		}
	}
	state := gin.H{
		"sampleId": s.SampleID, "requestId": s.RequestID, "requesterId": s.RequesterID,
		"origin": gin.H{"latitude": s.Origin.Latitude, "longitude": s.Origin.Longitude},
		"originType": originType,
		"requestedAt": s.RequestedAt.Format(time.RFC3339Nano),
		"deliveryDeadline": s.DeliveryDeadline.Format(time.RFC3339Nano),
		"sampleTypeId": s.SampleTypeID,
		"containerType": s.ContainerType,
		"temperatureMinC": s.TemperatureMinC,
		"temperatureMaxC": s.TemperatureMaxC,
		"incompatibleSampleTypes": inc,
		"serviceability": "serviceable",
		"activeAssignmentIds": []uuid.UUID{},
		"state": gin.H{"status": status},
		"timeline": tl,
		"locationStale": isStale(latRecAt),
	}
	if activeJ != nil {
		state["activeJourneyId"] = activeJ
	}
	if currentHolder != nil {
		state["currentHolderId"] = currentHolder
	}
	if targetLab != nil {
		state["targetLaboratoryId"] = targetLab
	}
	if latRec != nil && lonRec != nil {
		state["latestLocation"] = gin.H{"latitude": *latRec, "longitude": *lonRec}
	}
	if latRecAt != nil {
		state["locationRecordedAt"] = latRecAt.Format(time.RFC3339Nano)
	}
	// Populate activeAssignmentIds.
	rows, _ := globalState.PG.Query(ctx, `SELECT assignment_id FROM assignments WHERE journey_id=$1 AND status IN ('pending','in_progress')`, activeJ)
	for rows.Next() {
		var aid uuid.UUID
		if err := rows.Scan(&aid); err == nil {
			state["activeAssignmentIds"] = append(state["activeAssignmentIds"].([]uuid.UUID), aid)
		}
	}
	rows.Close()
	return state, APIError{}
}

// currentSession returns the active auth.Session; defined in middleware.go.
var _ = currentSession

func ptrString(p *uuid.UUID) string {
	if p == nil {
		return ""
	}
	return p.String()
}

func isStale(t *time.Time) bool {
	if t == nil {
		return true
	}
	return time.Since(*t) > 30*time.Minute
}

func idempotencyLookup(ctx context.Context, key string) (gin.H, bool) {
	val, err := globalState.Redis.Get(ctx, "idem:"+key).Result()
	if err != nil || val == "" {
		return nil, false
	}
	var out gin.H
	if err := json.Unmarshal([]byte(val), &out); err != nil {
		return nil, false
	}
	return out, true
}

func idempotencyStore(ctx context.Context, key string, v gin.H) {
	if globalState == nil || globalState.Redis == nil {
		return
	}
	b, _ := json.Marshal(v)
	_ = globalState.Redis.Set(ctx, "idem:"+key, string(b), 24*time.Hour).Err()
}

var _ = json.Marshal

