package api

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"labdeliver/backend/internal/auth"
	"labdeliver/backend/internal/store"
)

func loadUserRow(ctx context.Context, id uuid.UUID) (store.User, error) {
	row := globalState.PG.QueryRow(ctx, `
		SELECT user_id, username, password_hash, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''),
		       roles, qualifications, certifications, assigned_location_id, active, available, capacity_units, decline_count,
		       created_at, updated_at
		FROM users WHERE user_id = $1
	`, id)
	var u store.User
	var assigned *uuid.UUID
	var certsJSON []byte
	if err := row.Scan(&u.UserID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&u.Roles, &u.Qualifications, &certsJSON, &assigned, &u.Active, &u.Available, &u.CapacityUnits, &u.DeclineCount,
		&u.CreatedAt, &u.UpdatedAt); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return u, Err(http.StatusNotFound, "not_found", "user not found")
		}
		return u, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	u.AssignedLocationID = assigned
	_ = json.Unmarshal(certsJSON, &u.Certifications)
	return u, nil
}

func loadUserByUsername(ctx context.Context, username string) (store.User, error) {
	var id uuid.UUID
	row := globalState.PG.QueryRow(ctx, `SELECT user_id FROM users WHERE username = $1`, username)
	if err := row.Scan(&id); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return store.User{}, Err(http.StatusNotFound, "not_found", "user not found")
		}
		return store.User{}, err
	}
	return loadUserRow(ctx, id)
}

// handleCreateUser creates a user with the supplied roles + qualifications.
func handleCreateUser(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		Username           string             `json:"username"`
		InitialPassword    string             `json:"initialPassword"`
		Email              string             `json:"email"`
		FullName           string             `json:"fullName"`
		Phone              string             `json:"phone"`
		Roles              []string           `json:"roles"`
		Qualifications     []string           `json:"qualifications"`
		Certifications     []store.Cert       `json:"certifications"`
		Active             bool               `json:"active"`
		AssignedLocationID *string            `json:"assignedLocationId"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Username == "" || in.InitialPassword == "" || len(in.Roles) == 0 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "username, initialPassword and roles are required"))
		return
	}
	if err := validateRoles(in.Roles); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	hash, err := auth.HashPassword(in.InitialPassword)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "hash failure"))
		return
	}
	id := uuid.New()
	certs, _ := json.Marshal(in.Certifications)
	assigned := uuid.Nil
	if in.AssignedLocationID != nil && *in.AssignedLocationID != "" {
		assigned, err = uuid.Parse(*in.AssignedLocationID)
		if err != nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid assignedLocationId"))
			return
		}
	}
	if assigned != uuid.Nil {
		// validate exists
		var exists bool
		_ = globalState.PG.QueryRow(c.Request.Context(), `SELECT EXISTS(SELECT 1 FROM locations WHERE location_id=$1)`, assigned).Scan(&exists)
		if !exists {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "assignedLocationId not found"))
			return
		}
	}
	_, err = globalState.PG.Exec(c.Request.Context(), `
		INSERT INTO users (user_id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, assigned_location_id, active, available, capacity_units)
		VALUES ($1,$2,$3,NULLIF($4,''),NULLIF($5,''),NULLIF($6,''),$7,$8,$9::jsonb,$10,$11,TRUE,$12)
	`, id, in.Username, hash, in.Email, in.FullName, in.Phone, in.Roles, in.Qualifications, string(certs), nullUUID(assigned), in.Active, 5)
	if err != nil {
		WriteError(c, Err(http.StatusConflict, "duplicate_user", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "create_user", "user", id.String(), true, map[string]any{
		"username": in.Username, "roles": in.Roles,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"userId": id}})
}

// handleUpdateUserAccess updates role/qualification/certification/active status.
func handleUpdateUserAccess(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		UserID             string        `json:"userId"`
		Roles              []string      `json:"roles"`
		Qualifications     []string      `json:"qualifications"`
		Certifications     []store.Cert  `json:"certifications"`
		Active             bool          `json:"active"`
		AssignedLocationID *string       `json:"assignedLocationId"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
