	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
		return
	}
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "update_user_access", "user", id.String(), true, map[string]any{
		"roles": in.Roles, "active": in.Active,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"userId": id}})
}

