package api

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// haversineKm returns the distance between two coordinates in kilometres.
func haversineKm(aLat, aLon, bLat, bLon float64) float64 {
	const R = 6371.0
	toRad := func(d float64) float64 { return d * math.Pi / 180 }
	dLat := toRad(bLat - aLat)
	dLon := toRad(bLon - aLon)
	x := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(toRad(aLat))*math.Cos(toRad(bLat))*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(x), math.Sqrt(1-x))
	return R * c
}

// planInputs is the minimum data we need to construct a journey plan.
type planInputs struct {
	SampleTypeID uuid.UUID
	ContainerType string
	TemperatureMin float64
	TemperatureMax float64
	Incompatible   []uuid.UUID
	RequiresCooled bool
	BatchingAllowed bool
	Origin         coord
	OriginType     string
	OriginNodeID   *uuid.UUID
	Earliest       time.Time
	Latest         time.Time
	Deadline       time.Time
	HandlingMinutes int
}

// planOutput describes the result of building a journey.
type planOutput struct {
	Mode        string
	Stops       []map[string]any
	Legs        []map[string]any
	SampleIDs   []uuid.UUID
	EstDelivery time.Time
	TotalCost   float64
}

// buildJourneyPlan creates a journey + assignments for one or more samples
// starting from the same point. It reserves capacity on legs and the
// destination and returns the created ids in stopIds/legIds.
func buildJourneyPlan(ctx context.Context, samples []uuid.UUID, inputs planInputs) (*planOutput, APIError) {
	if len(samples) == 0 {
		return nil, Err(0, "no_samples", "no samples provided")
	}
	// Resolve sample types to validate compatibility.
	for _, s := range samples {
		// verify the sample belongs to the inputs
		var st uuid.UUID
		if err := globalState.PG.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE sample_id=$1`, s).Scan(&st); err != nil {
			return nil, Err(404, "not_found", "sample not found")
		}
	}
	// Decide whether batching is allowed. Pulse samples must not be batched.
	requiresSolo := false
	for _, s := range samples {
		var name string
		if err := globalState.PG.QueryRow(ctx, `
			SELECT st.name FROM samples s JOIN sample_types st ON st.sample_type_id=s.sample_type_id WHERE s.sample_id=$1
		`, s).Scan(&name); err == nil {
			if name == "Pulse" {
				requiresSolo = true
			}
		}
	}
	mode := "direct"
	if len(samples) > 1 && !requiresSolo {
		mode = "batched"
	}
	if inputs.OriginType == "home" || inputs.OriginType == "clinic" {
		// Need a stop at a collection point near origin.
		mode = "multi_stop"
	}
	// Compute the route: find a path from origin to a laboratory that accepts the sample type.
	plan, err := computeRoute(ctx, inputs, requiresSolo, len(samples), samples)
	if err != nil {
		return nil, Err(409, "no_route", err.Error())
	}
	return plan, APIError{}
}

func computeRoute(ctx context.Context, inputs planInputs, solo bool, sampleCount int, samples []uuid.UUID) (*planOutput, APIError) {
	// Find accepting laboratory.
	rows, err := globalState.PG.Query(ctx, `
		SELECT la.location_id, l.latitude, l.longitude
		FROM laboratory_acceptance la
		JOIN locations l ON l.location_id = la.location_id
		WHERE la.sample_type_id=$1 AND la.accepts=TRUE AND l.active=TRUE
	`, inputs.SampleTypeID)
	if err != nil {
		return nil, Err(500, "internal_error", err.Error())
	}
	defer rows.Close()
	type labRec struct {
		ID        uuid.UUID
		Latitude  float64
		Longitude float64
	}
	var labs []labRec
	for rows.Next() {
		var r labRec
		if err := rows.Scan(&r.ID, &r.Latitude, &r.Longitude); err == nil {
			labs = append(labs, r)
		}
	}
	if len(labs) == 0 {
		return nil, Err(409, "no_accepting_laboratory", "no laboratory accepts this sample type")
	}
	// Select nearest lab to deadline horizon - simplest is nearest lab.
	var (
		bestPlan    *planOutput
		bestEta     = time.Time{}
		bestArrival = time.Time{}
	)
	now := time.Now().UTC()
	collectAt := inputs.Latest
	if collectAt.IsZero() {
		collectAt = now
	}
	for _, lab := range labs {
		// Find active location near origin for pickup.
		pickupLoc, pickFn := findPickupLocation(ctx, inputs)
		if pickupLoc == nil {
			continue
		}
		// Try direct leg from pickup to lab.
		eta := travelEta(ctx, pickupLoc.ID, lab.ID, inputs.RequiresCooled, collectAt, inputs.HandlingMinutes)
		if eta.After(inputs.Deadline) {
			continue
		}
		if !hasCapacity(ctx, pickupLoc.ID, lab.ID, sampleCount, inputs.RequiresCooled) {
			continue
		}
		stops := []map[string]any{}
		legs := []map[string]any{}
		// First stop: pickup.
		stopID := uuid.New()
		stops = append(stops, map[string]any{
			"stopId": stopID, "locationId": pickupLoc.ID, "stopType": "pickup",
			"sequence": 1, "estimatedAt": collectAt.Format(time.RFC3339Nano),
			"dwellMinutes": 0, "coordinate": coord{Latitude: pickupLoc.Latitude, Longitude: pickupLoc.Longitude},
		})
		// Direct leg pickup -> lab.
		legID := uuid.New()
		legs = append(legs, map[string]any{
			"assignmentId": legID, "sequence": 1, "status": "pending",
			"fromLocationId": pickupLoc.ID, "toLocationId": lab.ID,
		})
		// Add intermediate stops if multi-hop.
		midPath, ok := findPath(ctx, pickupLoc.ID, lab.ID, inputs.RequiresCooled)
		if !ok {
			continue
		}
		seq := 1
		cur := collectAt
		prevID := pickupLoc.ID
		if len(midPath) > 1 {
			// Add handoff stops
			for i, hop := range midPath[1 : len(midPath)-1] {
				_ = i
				stopID := uuid.New()
				hopLoc, _ := loadLocationRow(ctx, hop)
				cur = cur.Add(time.Duration(hopLoc.HandlingMinutes) * time.Minute)
				stops = append(stops, map[string]any{
					"stopId": stopID, "locationId": hop, "stopType": "handoff",
					"sequence": seq + 1, "estimatedAt": cur.Format(time.RFC3339Nano),
					"dwellMinutes": hopLoc.HandlingMinutes, "coordinate": coord{Latitude: hopLoc.Coordinate.Latitude, Longitude: hopLoc.Coordinate.Longitude},
				})
				seq++
			}
			// replace direct leg with multiple legs.
			legs = nil
			for i := 0; i < len(midPath)-1; i++ {
				legID := uuid.New()
				eta := travelEta(ctx, midPath[i], midPath[i+1], inputs.RequiresCooled, cur, 0)
				legs = append(legs, map[string]any{
					"assignmentId": legID, "sequence": i + 1, "status": "pending",
					"fromLocationId": midPath[i], "toLocationId": midPath[i+1],
					"workerId": nil, "estimatedAt": eta.Format(time.RFC3339Nano),
				})
				cur = eta
			}
		}
		// Delivery stop
		stopID = uuid.New()
		stops = append(stops, map[string]any{
			"stopId": stopID, "locationId": lab.ID, "stopType": "delivery",
			"sequence": seq + 1, "estimatedAt": cur.Format(time.RFC3339Nano),
			"dwellMinutes": 0, "coordinate": coord{Latitude: lab.Latitude, Longitude: lab.Longitude},
		})
		if cur.After(inputs.Deadline) {
			continue
		}
		// Reserve capacity on each leg, the pickup and the lab.
		if err := reserveRouteCapacity(ctx, midPath, sampleCount, inputs.RequiresCooled); err != nil {
			continue
		}
		// Insert journey
		journeyID := uuid.New()
		_, err := globalState.PG.Exec(ctx, `
			INSERT INTO journeys (journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units)
			VALUES ($1, 1, $2, 'planned', $3, $4)
		`, journeyID, "direct", cur, computeCost(midPath, ctx))
		if err != nil {
			return nil, Err(500, "internal_error", err.Error())
		}
		// Insert stops.
		for _, s := range stops {
			b, _ := json.Marshal(s["coordinate"])
			var c coord
			_ = json.Unmarshal(b, &c)
			_, err := globalState.PG.Exec(ctx, `
				INSERT INTO journey_stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
				VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
			`, s["stopId"], journeyID, s["locationId"], s["stopType"], s["sequence"], parseTime(s["estimatedAt"]), s["dwellMinutes"], c.Latitude, c.Longitude)
			if err != nil {
				return nil, Err(500, "internal_error", err.Error())
			}
		}
		// Insert legs.
		for _, l := range legs {
			_, err := globalState.PG.Exec(ctx, `
				INSERT INTO assignments (assignment_id, journey_id, kind, from_location_id, to_location_id, sequence, status, requires_cooled, reserved_capacity)
				VALUES ($1,$2,'transport',$3,$4,$5,'pending',$6,$7)
			`, l["assignmentId"], journeyID, l["fromLocationId"], l["toLocationId"], l["sequence"], inputs.RequiresCooled, sampleCount)
			if err != nil {
				return nil, Err(500, "internal_error", err.Error())
			}
		}
		// Bind samples to the journey and write current holder.
		for _, sid := range samples {
			_, _ = globalState.PG.Exec(ctx, `
				UPDATE samples SET active_journey_id=$2, status='in_transit', current_holder_id=NULL, location_recorded_at=NOW() WHERE sample_id=$1
			`, sid, journeyID)
		}
		plan := &planOutput{
			Mode:        modeString(stops),
			Stops:       stops,
			Legs:        legs,
			SampleIDs:   samples,
			EstDelivery: cur,
			TotalCost:   computeCost(midPath, ctx),
		}
		_ = pickupLoc
		_ = pickFn
		_ = lab
		_ = bestEta
		_ = bestArrival
		return plan, APIError{}
	}
	if bestPlan == nil {
		return nil, Err(409, "deadline_unreachable", "cannot meet deadline")
	}
	return bestPlan, APIError{}
}

func modeString(stops []map[string]any) string {
	if len(stops) <= 2 {
		return "direct"
	}
	return "multi_stop"
}

func findPickupLocation(ctx context.Context, inputs planInputs) (*storeLocation, string) {
	if inputs.OriginType == "node" && inputs.OriginNodeID != nil {
		loc, _ := loadLocationRow(ctx, *inputs.OriginNodeID)
		if loc.Active {
			return &storeLocation{ID: loc.LocationID, Latitude: loc.Coordinate.Latitude, Longitude: loc.Coordinate.Longitude}, "node"
		}
	}
	// find an active collection point within 5km of origin.
	rows, err := globalState.PG.Query(ctx, `SELECT location_id, latitude, longitude FROM locations WHERE active=TRUE AND functions->>'collection_point' = 'true'`)
	if err != nil {
		return nil, ""
	}
	defer rows.Close()
	var best *storeLocation
	bestDist := math.MaxFloat64
	for rows.Next() {
		var s storeLocation
		if err := rows.Scan(&s.ID, &s.Latitude, &s.Longitude); err == nil {
			d := haversineKm(inputs.Origin.Latitude, inputs.Origin.Longitude, s.Latitude, s.Longitude)
			if d <= 5 && d < bestDist {
				bestDist = d
				best = &s
			}
		}
	}
	return best, "collection_point"
}

type storeLocation struct {
	ID        uuid.UUID
	Latitude  float64
	Longitude float64
}

func travelEta(ctx context.Context, from, to uuid.UUID, cooled bool, fromTime time.Time, dwell int) time.Time {
	row := globalState.PG.QueryRow(ctx, `SELECT travel_minutes FROM connections WHERE from_location_id=$1 AND to_location_id=$2 AND active=TRUE AND cooled=$3 LIMIT 1`, from, to, cooled)
	var mins int
	if err := row.Scan(&mins); err != nil {
		// try non-cooled if cooled unavailable
		row = globalState.PG.QueryRow(ctx, `SELECT travel_minutes FROM connections WHERE from_location_id=$1 AND to_location_id=$2 AND active=TRUE LIMIT 1`, from, to)
		_ = row.Scan(&mins)
	}
	return fromTime.Add(time.Duration(mins+dwell) * time.Minute)
}

func hasCapacity(ctx context.Context, from, to uuid.UUID, units int, cooled bool) bool {
	var available, reserved, capacity int
	if err := globalState.PG.QueryRow(ctx, `
		SELECT capacity_units, reserved_units FROM connections WHERE from_location_id=$1 AND to_location_id=$2 AND active=TRUE LIMIT 1
	`, from, to).Scan(&capacity, &reserved); err == nil {
		if cooled {
			var ca, cr int
			if err := globalState.PG.QueryRow(ctx, `SELECT cooled_capacity_units, cooled_reserved_units FROM connections WHERE from_location_id=$1 AND to_location_id=$2 AND active=TRUE LIMIT 1`, from, to).Scan(&ca, &cr); err == nil {
				return ca-cr >= units
			}
		}
		return capacity-reserved >= units
	}
	return false
}

// findPath returns an ordered list of location ids from from->to using BFS over active connections.
func findPath(ctx context.Context, from, to uuid.UUID, cooled bool) ([]uuid.UUID, bool) {
	parents := map[uuid.UUID]uuid.UUID{from: uuid.Nil}
	queue := []uuid.UUID{from}
	found := false
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == to {
			found = true
			break
		}
		rows, err := globalState.PG.Query(ctx, `
			SELECT to_location_id FROM connections WHERE from_location_id=$1 AND active=TRUE
		`, cur)
		if err != nil {
			continue
		}
		defer rows.Close()
		for rows.Next() {
			var next uuid.UUID
			if err := rows.Scan(&next); err == nil {
				if _, seen := parents[next]; !seen {
					parents[next] = cur
					queue = append(queue, next)
				}
			}
		}
	}
	if !found {
		return nil, false
	}
	// Reconstruct path.
	var path []uuid.UUID
	for n := to; n != uuid.Nil; n = parents[n] {
		path = append([]uuid.UUID{n}, path...)
		if n == from {
			break
		}
	}
	return path, true
}

func reserveRouteCapacity(ctx context.Context, path []uuid.UUID, units int, cooled bool) error {
	for i := 0; i < len(path)-1; i++ {
